// 历史人物（公元 1—9 世纪）：耶稣、曹操、诸葛亮、君士坦丁、穆罕默德、唐太宗、玄奘、武则天、鉴真、李白、查理曼。
// 年代为约数的人物以 approx 标注；地点坐标取遗址或今城市位置，传统认定的地点在文案中点明。
import type { Figure } from '../../types.ts';
import { w } from './waypoint.ts';

export const FIGURES_CLASSICAL: Figure[] = [
  {
    id: 'jesus', name: { zh: '耶稣', en: 'Jesus' }, birth: -4, death: 30, approx: true,
    title: { zh: '基督教核心人物', en: 'Central figure of Christianity' }, region: 'west-asia', sprite: 'walker',
    summary: {
      zh: '基督教的核心人物，生活于罗马帝国治下的犹太和加利利地区。据《新约》记载，他在加利利海一带传道，宣讲爱与悔改，约公元30年（一说33年）在耶路撒冷被罗马总督本丢·彼拉多判处钉十字架。其门徒相信他复活，并将其教导传遍罗马帝国，形成基督教。',
      en: "The central figure of Christianity, who lived in Judaea and Galilee under Roman rule. According to the New Testament he preached around the Sea of Galilee, teaching love of God and neighbour and calling for repentance, and was crucified in Jerusalem about AD 30 (some prefer 33) on the order of the Roman prefect Pontius Pilate. His followers came to believe that he had risen from the dead, and they carried his teaching across the Roman Empire, where it grew into Christianity.",
    },
    route: [
      w(-4, 35.2, 31.705,
        ['伯利恒（今巴勒斯坦伯利恒）', '据《新约》记载生于伯利恒', '《马太福音》和《路加福音》都说耶稣生于大卫王的故乡伯利恒，时在大希律王在位末年，学者多据此推定为公元前6—前4年。4世纪起，这里的一处洞穴被认作诞生地，其上建有圣诞教堂。'],
        ["Bethlehem (West Bank)", "Born in Bethlehem, according to the Gospels", "The Gospels of Matthew and Luke place the birth of Jesus in Bethlehem, the town of King David, late in the reign of Herod the Great, which is why scholars usually date it between 6 and 4 BC. Since the 4th century a grotto here, now beneath the Church of the Nativity, has been venerated as the birthplace."],
        { wiki: { zh: '圣诞教堂', en: 'Church of the Nativity' } }),
      w(1, 35.3, 32.7,
        ['拿撒勒（加利利，今以色列北部）', '在加利利的拿撒勒长大', '福音书说耶稣一家定居在加利利山间的小村拿撒勒，约瑟是木匠，耶稣因此被称为“拿撒勒人耶稣”。关于他的童年和青年时代，福音书几乎没有记载。'],
        ["Nazareth (Galilee, now northern Israel)", "Grows up in Nazareth in Galilee", "The Gospels say the family settled in Nazareth, a small village in the hills of Galilee, where Joseph worked as a carpenter; hence the name Jesus of Nazareth. They record almost nothing about his childhood and early adult life."]),
      w(9, 35.2355, 31.778,
        ['耶路撒冷圣殿', '十二岁随父母上耶路撒冷过节', '据《路加福音》，耶稣十二岁那年随父母到耶路撒冷守逾越节，返程时父母发现他不在同行的人中，三天后才在圣殿里找到他，他正坐在教师中间边听边问。这是福音书中唯一的少年时代故事，年份为推算。'],
        ["Temple in Jerusalem", "Visits the Temple at the age of twelve", "Luke's Gospel tells how the twelve-year-old Jesus went up to Jerusalem with his parents for Passover and was missed on the journey home. After three days they found him in the Temple, sitting among the teachers, listening and asking questions. It is the only Gospel story of his boyhood; the year is an estimate."]),
      w(28, 35.55, 31.84,
        ['约旦河（耶利哥以东）', '受施洗约翰洗礼，开始传道', '施洗约翰在约旦河边呼吁人悔改，耶稣也来到这里接受洗礼。福音书把这件事作为他公开传道的起点，《路加福音》说他当时约三十岁。传统上认定的受洗处在耶利哥以东的约旦河畔。'],
        ["Jordan River (east of Jericho)", "Baptised by John the Baptist", "John the Baptist was calling people to repentance beside the Jordan, and Jesus came to be baptised by him. The Gospels treat the event as the start of his public ministry; Luke says he was about thirty. The traditional site lies on the river east of Jericho."],
        { wiki: { zh: '耶稣受洗', en: 'Baptism of Jesus' } }),
      w(28, 35.43, 31.87,
        ['犹大旷野（耶利哥附近）', '在旷野禁食四十天', '据对观福音，耶稣受洗后退到犹大旷野，禁食四十昼夜，并在那里拒绝了魔鬼的三次试探。后世传统把耶利哥城西的一座山认作试探发生的地方，称为“试探山”。'],
        ["Judaean Desert (near Jericho)", "Fasts forty days in the wilderness", "According to the Synoptic Gospels, Jesus withdrew after his baptism into the Judaean wilderness, fasted for forty days and nights and resisted three temptations by the devil. Later tradition identified a hill west of Jericho, the Mount of Temptation, as the place."]),
      w(28, 35.34, 32.75,
        ['迦拿（加利利，传统认为即今卡夫尔坎纳）', '迦拿婚宴', '《约翰福音》记载，耶稣和母亲、门徒在加利利的迦拿赴一场婚宴，酒用尽时他把水变成酒，这被称为他所行的第一个“神迹”。迦拿的确切位置尚无定论，拿撒勒东北的卡夫尔坎纳是传统认定的地点。'],
        ["Cana (Galilee; traditionally Kafr Kanna)", "The wedding at Cana", "John's Gospel relates that at a wedding in Cana of Galilee, attended with his mother and disciples, Jesus turned water into wine when the supply ran out, the first of his 'signs'. The site of Cana is uncertain; Kafr Kanna, north-east of Nazareth, is the traditional candidate."]),
      w(28, 35.575, 32.88,
        ['迦百农（加利利海北岸）', '以加利利海畔为中心传道', '耶稣离开拿撒勒，住到加利利海北岸的渔村迦百农，在湖边呼召彼得、安得烈、雅各和约翰等渔夫作门徒，在会堂里讲道，并往来于周围村镇。《马太福音》称这里为他“自己的城”。'],
        ["Capernaum (north shore of the Sea of Galilee)", "Makes the lakeside his base for preaching", "Leaving Nazareth, Jesus settled in the fishing village of Capernaum, called fishermen such as Peter, Andrew, James and John to follow him, taught in its synagogue and travelled through the surrounding towns. Matthew's Gospel calls it 'his own town'."],
        { wiki: { zh: '迦百农', en: 'Capernaum' } }),
      w(29, 35.556, 32.881,
        ['八福山（加利利海西北岸）', '登山宝训', '《马太福音》第5至7章记载耶稣上山向门徒和众人讲道，内容包括“八福”、主祷文和“爱你们的仇敌”等教导，是基督教伦理最集中的表述。福音书没有指明是哪座山，迦百农附近的这处山坡是传统认定的地点。'],
        ["Mount of Beatitudes (north-west shore of the Sea of Galilee)", "The Sermon on the Mount", "Chapters 5 to 7 of Matthew present Jesus teaching his disciples and the crowds on a mountain: the Beatitudes, the Lord's Prayer and the command to love one's enemies. The Gospel does not name the hill; this slope near Capernaum is the traditional site."],
        { wiki: { zh: '登山宝训', en: 'Sermon on the Mount' } }),
      w(29, 35.549, 32.873,
        ['塔布加（加利利海畔）', '五饼二鱼', '四部福音书都记载，耶稣在加利利海边的野地用五个饼、两条鱼使约五千人吃饱。福音书说事情发生在伯赛大附近的偏僻地方，自4世纪起，湖西北岸的塔布加被朝圣者认作纪念地。'],
        ["Tabgha (shore of the Sea of Galilee)", "Feeding of the five thousand", "All four Gospels tell how Jesus fed a crowd of about five thousand with five loaves and two fish in a lonely place by the lake, which they set near Bethsaida. Since the 4th century pilgrims have commemorated the event at Tabgha on the north-west shore."]),
      w(29, 35.694, 33.248,
        ['该撒利亚腓立比（今戈兰高地巴尼亚斯）', '彼得认耶稣为基督', '耶稣带门徒北上到约旦河源头附近的该撒利亚腓立比一带，问他们“你们说我是谁”，彼得回答“你是基督”。据对观福音，此后耶稣开始向门徒预言自己将在耶路撒冷受难。'],
        ["Caesarea Philippi (now Banias, Golan Heights)", "Peter declares him the Messiah", "Near Caesarea Philippi, by the sources of the Jordan, Jesus asked his disciples, 'Who do you say I am?' and Peter answered, 'You are the Messiah.' In the Synoptic Gospels, Jesus then begins to speak of the suffering that awaits him in Jerusalem."]),
      w(29, 35.39, 32.687,
        ['他泊山（加利利）', '登山变像', '对观福音记载，耶稣带彼得、雅各、约翰登上一座高山，在他们面前改变形像，衣服洁白发光。福音书没有说出山名，自3世纪以来的教会传统认为是耶斯列平原上孤峰突起的他泊山。'],
        ["Mount Tabor (Galilee)", "The Transfiguration", "The Synoptic Gospels relate that Jesus took Peter, James and John up a high mountain, where his appearance changed and his clothes shone white. The mountain is unnamed; church tradition since the 3rd century has identified it with Mount Tabor, an isolated hill above the Jezreel Valley."],
        { wiki: { zh: '他泊山', en: 'Mount Tabor' } }),
      w(30, 35.444, 31.871,
        ['耶利哥（约旦河谷）', '经耶利哥前往耶路撒冷', '逾越节前，耶稣与门徒沿约旦河谷南下，经耶利哥上耶路撒冷。福音书说他在这里医治了路旁的盲人，《路加福音》还记载税吏长撒该爬上桑树看他，耶稣便到他家中作客。'],
        ["Jericho (Jordan valley)", "Passes through Jericho towards Jerusalem", "Before Passover, Jesus and his disciples came down the Jordan valley and went up to Jerusalem by way of Jericho. The Gospels say he healed a blind beggar by the road here, and Luke adds the story of Zacchaeus, the tax collector who climbed a sycamore tree to see him."]),
      w(30, 35.2613, 31.7714,
        ['伯大尼（橄榄山东麓）', '住在伯大尼', '伯大尼在橄榄山东坡，离耶路撒冷约3公里，是马大、马利亚和拉撒路姐弟的家。《约翰福音》记载耶稣在这里使拉撒路复活；最后一周，他白天进城，晚上回到这里住宿。'],
        ["Bethany (eastern slope of the Mount of Olives)", "Stays at Bethany", "Bethany, about 3 km from Jerusalem on the far side of the Mount of Olives, was the home of Martha, Mary and Lazarus. John's Gospel sets the raising of Lazarus here, and during his last week Jesus went into the city by day and returned here to lodge."]),
      w(30, 35.2355, 31.778,
        ['耶路撒冷圣殿', '进入耶路撒冷，洁净圣殿', '福音书记载，耶稣骑驴从橄榄山进城，人群手持棕树枝夹道欢迎。他在圣殿外院赶走做买卖的人，推倒兑换银钱者的桌子，随后几天在殿里讲道，与祭司长和文士的冲突日益尖锐。'],
        ["Temple in Jerusalem", "Enters Jerusalem and clears the Temple", "The Gospels describe Jesus riding into the city on a donkey from the Mount of Olives while crowds waved palm branches. In the outer court of the Temple he drove out the traders and overturned the money changers' tables, and his teaching there over the following days sharpened the conflict with the chief priests."]),
      w(30, 35.2397, 31.7793,
        ['客西马尼园（橄榄山脚）', '最后的晚餐后在客西马尼被捕', '逾越节前夕，耶稣与十二门徒在城中吃了最后的晚餐，然后来到橄榄山脚的客西马尼园祷告。门徒犹大带人到园中，耶稣被捕，连夜被带到大祭司该亚法那里受审。'],
        ["Gethsemane (foot of the Mount of Olives)", "Arrested after the Last Supper", "On the eve of Passover Jesus shared a last supper with the twelve disciples in the city and then went to pray in the garden of Gethsemane at the foot of the Mount of Olives. There Judas led in an armed party, and Jesus was arrested and taken by night before the high priest Caiaphas."]),
      w(30, 35.23, 31.78,
        ['耶路撒冷（各各他）', '被罗马总督判处钉十字架', '罗马总督本丢·彼拉多判处耶稣死刑，他在城外的各各他（意为“髑髅地”）被钉十字架，当天葬在附近的石墓中。门徒相信他在第三天复活，基督教由此兴起；传统认定的受难处和墓穴如今都在圣墓教堂内。'],
        ["Jerusalem (Golgotha)", "Crucified by order of the Roman governor", "The Roman prefect Pontius Pilate sentenced Jesus to death, and he was crucified at Golgotha, 'the place of the skull', outside the city wall and buried in a rock tomb nearby. His followers believed he rose on the third day; the traditional sites of both are enclosed in the Church of the Holy Sepulchre."],
        { event: 'crucifixion-of-jesus' }),
    ],
    wiki: { zh: '耶稣', en: 'Jesus' },
  },
  {
    id: 'cao-cao', name: { zh: '曹操', en: 'Cao Cao' }, birth: 155, death: 220,
    title: { zh: '政治家、军事家、诗人', en: 'Statesman, general and poet' }, region: 'china', lineage: 'china', sprite: 'horse',
    summary: {
      zh: '东汉末年政治家、军事家、文学家。他“挟天子以令诸侯”，在官渡之战中击败袁绍，统一北方，推行屯田、唯才是举等政策。赤壁之战失利后，逐渐形成三国鼎立之势。曹操诗文雄健，与其子曹丕、曹植并称“三曹”；他去世后，曹丕代汉建立曹魏。',
      en: "Statesman, general and poet of the last decades of the Eastern Han. Keeping the emperor at his own base and ruling in his name, he defeated Yuan Shao at Guandu, reunified northern China, settled soldiers and refugees on state farms and recruited officials for talent rather than birth. His defeat at Red Cliffs in 208 left the land divided among three powers. Cao Cao was also a forceful poet, grouped with his sons Cao Pi and Cao Zhi as the 'Three Caos'. After his death Cao Pi ended the Han and founded the state of Wei.",
    },
    route: [
      w(155, 115.78, 33.85,
        ['谯县（今安徽亳州）', '生于沛国谯县', '曹操字孟德，父亲曹嵩是宦官中常侍曹腾的养子，后来官至太尉。出身宦官之家使他颇受士族轻视，史书说他少年时机警有权谋，任侠放荡，不治行业。'],
        ["Qiao (now Bozhou, Anhui)", "Born at Qiao in the state of Pei", "Cao Cao, courtesy name Mengde, was the son of Cao Song, the adopted heir of the powerful court eunuch Cao Teng. The eunuch connection made the family rich but was looked down on by the gentry. The histories describe the young Cao Cao as quick-witted, wilful and fond of adventure."]),
      w(174, 112.62, 34.72,
        ['洛阳（东汉都城）', '举孝廉，任洛阳北部尉', '二十岁时曹操被举为孝廉，出任负责都城北部治安的洛阳北部尉。他在衙门两侧悬挂五色棒，犯禁者不避豪强一律棒杀，连宦官蹇硕的叔父违禁夜行也被处死，京师为之肃然。'],
        ["Luoyang (Eastern Han capital)", "Named commandant of northern Luoyang", "Recommended as 'filial and incorrupt' at twenty, Cao Cao was put in charge of policing the northern district of the capital. He hung multicoloured staves at his gate and had offenders beaten regardless of rank; even the uncle of the eunuch Jian Shuo was flogged to death for breaking the curfew."]),
      w(184, 113.77, 34.22,
        ['颍川长社（今河南长葛）', '任骑都尉，镇压颍川黄巾', '184年黄巾起义爆发，曹操以骑都尉率军赶到颍川，与皇甫嵩、朱儁合兵大破黄巾军。他因功升任济南相，在任上奏免贪污的县官，禁绝当地盛行的淫祀。'],
        ["Changshe in Yingchuan (now Changge, Henan)", "Fights the Yellow Turbans as cavalry commandant", "When the Yellow Turban uprising broke out in 184, Cao Cao led a cavalry force to Yingchuan and joined Huangfu Song and Zhu Jun in routing the rebels there. He was rewarded with the post of Chancellor of Jinan, where he dismissed corrupt county officials and suppressed unauthorised local cults."]),
      w(189, 114.45, 34.68,
        ['陈留（今河南开封东南）', '散家财募兵，起兵讨伐董卓', '董卓入京废立皇帝，曹操不肯受其官职，改换姓名逃出洛阳。回到陈留后他变卖家产，在己吾招募到五千人，次年加入关东各州郡讨伐董卓的联军。'],
        ["Chenliu (south-east of Kaifeng, Henan)", "Raises an army against Dong Zhuo", "When Dong Zhuo seized the capital and deposed the emperor, Cao Cao refused office under him and slipped out of Luoyang under a false name. Back in Chenliu he sold family property, enlisted some five thousand men at Jiwu and the next year joined the eastern coalition against Dong Zhuo."]),
      w(190, 113.38, 34.79,
        ['荥阳汴水（今河南荥阳）', '汴水之战兵败负伤', '联军各部屯兵酸枣，观望不前，曹操独自率军西进，在荥阳汴水遭遇董卓部将徐荣，全军溃败。他本人中箭，坐骑受伤，靠堂弟曹洪让马才得以脱身。'],
        ["Bian River at Xingyang (Henan)", "Defeated and wounded at the Bian River", "While the coalition armies sat idle at Suanzao, Cao Cao pushed west on his own and met Dong Zhuo's general Xu Rong on the Bian River near Xingyang. His force was destroyed; hit by an arrow and with his horse wounded, he escaped only because his cousin Cao Hong gave up his own mount."]),
      w(192, 116.2, 35.9,
        ['寿张（今山东东平一带）', '入主兖州，收编青州兵', '青州黄巾攻入兖州，刺史刘岱战死，曹操被迎为兖州牧。他在寿张以东击败黄巾军，追到济北迫使其投降，从史称三十余万的降卒中挑选精锐编为“青州兵”，从此有了自己的地盘和主力部队。'],
        ["Shouzhang (near Dongping, Shandong)", "Takes Yan Province and forms the Qingzhou Corps", "When Yellow Turbans from Qing Province overran Yan Province and killed its inspector Liu Dai, Cao Cao was invited to take charge. He beat the rebels east of Shouzhang, pursued them to Jibei and accepted their surrender, forming the best of them into the Qingzhou Corps. He now had a territory and an army of his own."]),
      w(194, 115.03, 35.76,
        ['濮阳（今河南濮阳）', '与吕布争夺兖州', '曹操东征徐州陶谦时，部下张邈、陈宫迎吕布入兖州，全州只剩鄄城等三县未叛。他回师与吕布在濮阳相持百余日，次年在定陶、巨野连败吕布，才重新夺回兖州。'],
        ["Puyang (Henan)", "Fights Lü Bu for Yan Province", "While Cao Cao was campaigning against Tao Qian in Xu Province, his associates Zhang Miao and Chen Gong invited Lü Bu into Yan Province, and all but three counties went over. Cao Cao returned and fought Lü Bu around Puyang for more than a hundred days, then beat him at Dingtao and Juye in 195 and recovered the province."]),
      w(196, 113.83, 34.03,
        ['许县（今河南许昌）', '迎汉献帝都许', '汉献帝从长安辗转逃回残破的洛阳，曹操采纳荀彧的建议亲往迎接，把朝廷迁到许县，从此“挟天子以令诸侯”。同年他在许下募民屯田，当年得谷百万斛，解决了军粮问题。'],
        ["Xu (now Xuchang, Henan)", "Brings Emperor Xian to Xu", "Emperor Xian had struggled back from Chang'an to a ruined Luoyang. On Xun Yu's advice Cao Cao went to meet him and moved the court to Xu, and from then on issued commands in the emperor's name. The same year he set up state farms around Xu, which secured the grain supply for his armies."]),
      w(197, 112.53, 33.0,
        ['宛城（今河南南阳）', '宛城遭张绣突袭', '曹操南征宛城，张绣先降后叛，夜袭曹营。曹操受箭伤逃脱，长子曹昂、侄子曹安民和亲兵猛将典韦都死于此役。此后他又两次征讨张绣，直到199年张绣才再度归降。'],
        ["Wancheng (now Nanyang, Henan)", "Surprised by Zhang Xiu at Wancheng", "Zhang Xiu surrendered Wancheng to Cao Cao and then turned on him in a night attack. Cao Cao escaped wounded, but his eldest son Cao Ang, his nephew Cao Anmin and his bodyguard Dian Wei were killed. Two more campaigns followed before Zhang Xiu submitted for good in 199."]),
      w(198, 117.9, 34.12,
        ['下邳（今江苏睢宁古邳镇）', '围下邳，擒杀吕布', '曹操东征徐州，把吕布围困在下邳城中，并引泗水、沂水灌城。围城三个月后，吕布部将缚陈宫出降，吕布被擒，与陈宫、高顺一同被处死，降将张辽从此归入曹操麾下。'],
        ["Xiapi (now Gupi, Suining, Jiangsu)", "Besieges Xiapi and executes Lü Bu", "Marching east into Xu Province, Cao Cao shut Lü Bu up in Xiapi and flooded the city with the waters of the Si and Yi rivers. After three months Lü Bu's officers mutinied and he was captured and put to death with Chen Gong and Gao Shun; the general Zhang Liao came over to Cao Cao."],
        { wiki: { zh: '下邳之战', en: 'Battle of Xiapi' } }),
      w(200, 114.06, 34.73,
        ['官渡（今河南中牟）', '官渡之战大败袁绍', '占据河北四州的袁绍率大军南下，曹操以远少于对方的兵力在官渡相持数月，粮草将尽。他采纳降将许攸之计，亲率五千人夜袭乌巢，烧毁袁军粮草，袁军随即崩溃，北方的归属由此决定。'],
        ["Guandu (now Zhongmu, Henan)", "Defeats Yuan Shao at Guandu", "Yuan Shao, master of the four provinces north of the Yellow River, marched south with a far larger army, and Cao Cao held him at Guandu for months as his own supplies ran low. Acting on the defector Xu You's advice, he led five thousand men by night to burn Yuan's grain depot at Wuchao, and the northern army fell apart."],
        { wiki: { zh: '官渡之战', en: 'Battle of Guandu' } }),
      w(204, 114.4, 36.33,
        ['邺城（今河北临漳）', '攻克邺城，平定冀州', '袁绍死后诸子相争，曹操乘机北上围攻袁氏的大本营邺城，引漳水灌城，数月后破城。他自领冀州牧，把邺城作为自己的根据地，后来在城西北筑铜雀台，与文士们宴饮赋诗。'],
        ["Ye (now Linzhang, Hebei)", "Captures Ye and takes Ji Province", "After Yuan Shao's death his sons fought one another, and Cao Cao marched north to besiege Ye, the family stronghold, flooding it with the Zhang River. The city fell after several months. He made himself Governor of Ji Province and Ye his own base, later building the Bronze Bird Terrace, where he feasted and wrote verse with his literary circle."],
        { wiki: { zh: '邺城', en: 'Ye (Hebei)' } }),
      w(207, 119.4, 41.2,
        ['白狼山（今辽宁喀左一带）', '北征乌桓，归途作《观沧海》', '为消灭逃往辽西的袁尚、袁熙及其乌桓盟友，曹操由田畴引路出卢龙塞，穿行五百余里荒野，在白狼山一战斩杀乌桓首领蹋顿。《观沧海》一般认为是他这次班师途经碣石时所作。'],
        ["White Wolf Mountain (near Kazuo, Liaoning)", "Campaigns against the Wuhuan", "To finish off Yuan Shao's sons and their Wuhuan allies in Liaoxi, Cao Cao was guided by Tian Chou through the Lulong pass and across some five hundred li of wilderness. At White Wolf Mountain his vanguard killed the Wuhuan leader Tadun. His poem 'Viewing the Blue Sea' is generally thought to have been written at Mount Jieshi on the march home."],
        { wiki: { zh: '白狼山之战', en: 'Battle of White Wolf Mountain' } }),
      w(208, 113.67, 29.87,
        ['赤壁（今湖北赤壁）', '南征荆州，赤壁之战失利', '曹操南下，刘琮举荆州投降，他随即顺江东进，在赤壁与孙权、刘备联军隔江对峙。北方士兵不习水战，军中又流行疫病，周瑜部将黄盖诈降火攻，曹军战船尽毁，曹操经华容道退回北方。'],
        ["Red Cliffs (now Chibi, Hubei)", "Defeated at Red Cliffs", "After Liu Cong surrendered Jing Province, Cao Cao moved down the Yangtze and faced the allied forces of Sun Quan and Liu Bei at Red Cliffs. His northern troops were unused to fighting on water and weakened by disease, and a fire attack led by Huang Gai under a false surrender destroyed his fleet. He retreated north by the Huarong road."],
        { event: 'battle-of-red-cliffs' }),
      w(211, 110.24, 34.6,
        ['潼关（今陕西潼关）', '渭南之战击破马超、韩遂', '关中诸将马超、韩遂等起兵拒守潼关。曹操在正面与之相持，暗中派徐晃从蒲坂渡过黄河，自己再北渡迂回到渭水南岸，又用贾诩之计离间马、韩，一战击溃联军，关中从此平定。'],
        ["Tong Pass (Tongguan, Shaanxi)", "Defeats Ma Chao and Han Sui", "The warlords of Guanzhong under Ma Chao and Han Sui blocked Tong Pass. Cao Cao held their attention there while Xu Huang crossed the Yellow River upstream at Puban, then followed and worked round to the south bank of the Wei. Using Jia Xu's ruse to sow distrust between the two leaders, he broke the coalition and secured Guanzhong."]),
      w(213, 114.4, 36.33,
        ['邺城', '受封魏公，后进爵魏王', '汉献帝册封曹操为魏公，以冀州十郡为封国，加九锡，在邺城建立魏国的社稷宗庙。216年他进爵魏王，名义上仍是汉臣，实际上已拥有自己的朝廷，却始终没有称帝。'],
        ["Ye", "Made Duke of Wei, later King of Wei", "Emperor Xian enfeoffed Cao Cao as Duke of Wei with ten commanderies of Ji Province and the nine bestowments, and a Wei state with its own ancestral temple was set up at Ye. In 216 he was raised to King of Wei. He now had a court of his own in all but name, yet never took the imperial title."]),
      w(215, 107.03, 33.07,
        ['汉中（今陕西汉中）', '西征张鲁，取汉中', '曹操翻越秦岭进攻割据汉中近三十年的五斗米道首领张鲁，攻破阳平关，张鲁出降。他没有听从司马懿等人乘势入蜀的建议，留夏侯渊镇守而还；四年后夏侯渊在定军山阵亡，汉中落入刘备之手。'],
        ["Hanzhong (Shaanxi)", "Takes Hanzhong from Zhang Lu", "Crossing the Qinling range, Cao Cao attacked Zhang Lu, the Five Pecks of Rice leader who had ruled Hanzhong for nearly thirty years, forced Yangping Pass and received his surrender. He declined advice to press on into Shu and left Xiahou Yuan in command; four years later Xiahou Yuan fell at Mount Dingjun and Liu Bei took Hanzhong."],
        { wiki: { zh: '阳平关之战', en: 'Battle of Yangping' } }),
      w(220, 112.62, 34.72,
        ['洛阳', '病逝于洛阳', '曹操从汉中前线东归，又南下救援被关羽围困的樊城，220年正月回到洛阳后病逝。他遗令薄葬，葬于邺城以西的高陵。同年其子曹丕代汉称帝，追尊他为魏武帝。'],
        ["Luoyang", "Dies at Luoyang", "After the Hanzhong front and the relief of Fancheng, which Guan Yu had besieged, Cao Cao returned to Luoyang and died there early in 220. His will asked for a plain burial, and he was laid in the Gaoling tomb west of Ye. That year his son Cao Pi ended the Han and honoured him posthumously as Emperor Wu of Wei."]),
    ],
    wiki: { zh: '曹操', en: 'Cao Cao' },
  },
  {
    id: 'zhuge-liang', name: { zh: '诸葛亮', en: 'Zhuge Liang' }, birth: 181, death: 234,
    title: { zh: '蜀汉丞相', en: 'Chancellor of Shu Han' }, region: 'china', lineage: 'china', sprite: 'walker',
    summary: {
      zh: '三国时期蜀汉丞相，杰出的政治家、军事家。隐居隆中时为刘备提出“三分天下”的《隆中对》，后促成孙刘联盟，辅佐刘备建立蜀汉。刘备死后受托孤之重，南征北伐，鞠躬尽瘁，最终病逝于五丈原军中。所作《出师表》为千古名篇。',
      en: "Chancellor of Shu Han in the Three Kingdoms period and one of China's most admired statesmen. Living in retirement at Longzhong, he set out for Liu Bei the Longzhong Plan for a threefold division of the empire, then helped forge the alliance with Sun Quan and found the state of Shu Han. Entrusted with the young heir on Liu Bei's death, he pacified the south and led repeated northern campaigns against Wei until he died in camp on the Wuzhang Plains. His memorial known as the Chu Shi Biao is a classic of Chinese prose.",
    },
    route: [
      w(181, 118.47, 35.55,
        ['阳都（今山东沂南）', '生于琅琊阳都', '诸葛亮字孔明，出身琅琊的官宦人家，父亲诸葛珪做过泰山郡丞。他幼年丧父，与弟弟诸葛均由叔父诸葛玄抚养，时值黄巾起义之后，中原战乱不断。'],
        ["Yangdu (now Yinan, Shandong)", "Born at Yangdu in Langya", "Zhuge Liang, courtesy name Kongming, came from an official family of Langya; his father Zhuge Gui had been an assistant in Taishan commandery. Orphaned young, he and his brother Zhuge Jun were brought up by their uncle Zhuge Xuan as the north China plain slid into civil war."]),
      w(195, 115.89, 28.68,
        ['豫章（今江西南昌）', '随叔父诸葛玄南下豫章', '叔父诸葛玄被袁术任命为豫章太守，带着诸葛亮兄弟赴任。不久朝廷另派朱皓接任，诸葛玄失去官职，便投奔旧友、荆州牧刘表，诸葛亮由此来到荆州。年份为约数。'],
        ["Yuzhang (now Nanchang, Jiangxi)", "Travels south with his uncle to Yuzhang", "About 195 his uncle Zhuge Xuan was named Administrator of Yuzhang by Yuan Shu and took the two boys south with him. When the court sent Zhu Hao to replace him, Zhuge Xuan turned to an old acquaintance, Liu Biao, Governor of Jing Province, and so the family came to Jing."]),
      w(197, 112.06, 32.01,
        ['隆中（今湖北襄阳城西）', '隐居隆中，躬耕陇亩', '叔父去世后，诸葛亮在襄阳城西的隆中结庐而居，耕读约十年。隆中当时属南阳郡邓县，所以他在《出师表》中自称“躬耕于南阳”。他常自比管仲、乐毅，被名士庞德公称为“卧龙”。年份为约数。'],
        ["Longzhong (west of Xiangyang, Hubei)", "Lives as a farmer-scholar at Longzhong", "After his uncle died, about 197, Zhuge Liang built a cottage at Longzhong, west of Xiangyang, and for some ten years farmed and studied there. Longzhong then belonged to Nanyang commandery, hence his later phrase about ploughing his own fields in Nanyang. He likened himself to the ancient ministers Guan Zhong and Yue Yi and was nicknamed the 'Sleeping Dragon'."]),
      w(207, 112.06, 32.01,
        ['隆中', '刘备三顾茅庐，提出《隆中对》', '寄居荆州的刘备经徐庶推荐，三次到隆中才见到二十七岁的诸葛亮。诸葛亮为他分析天下形势：先取荆州、益州，外结孙权，内修政理，待机两路北伐以复兴汉室。此后他出山辅佐刘备。'],
        ["Longzhong", "Liu Bei's three visits and the Longzhong Plan", "On Xu Shu's recommendation Liu Bei, then a guest of Liu Biao, called three times before the young Zhuge Liang received him. Zhuge Liang laid out a strategy: take Jing and Yi provinces, ally with Sun Quan, govern well, and wait for the moment to strike north on two fronts and restore the Han. He then entered Liu Bei's service."],
        { wiki: { zh: '隆中对', en: 'Longzhong Plan' } }),
      w(208, 111.79, 30.82,
        ['当阳长坂（今湖北当阳）', '随刘备南撤，兵败长坂', '曹操南下，刘琮不战而降。刘备带着十余万百姓从樊城南撤，日行仅十余里，在当阳长坂被曹军精骑追上，全军溃散，只与诸葛亮、张飞、赵云等数十骑脱身，转往夏口。'],
        ["Changban, Dangyang (Hubei)", "Flees south with Liu Bei; rout at Changban", "When Cao Cao marched south and Liu Cong surrendered without a fight, Liu Bei retreated from Fancheng with a huge train of civilians, covering only a few miles a day. Cao Cao's cavalry caught the column at Changban; Liu Bei escaped with Zhuge Liang, Zhang Fei, Zhao Yun and a few dozen riders and made for Xiakou."]),
      w(208, 115.98, 29.71,
        ['柴桑（今江西九江）', '出使东吴，促成孙刘联盟', '诸葛亮自请出使，随鲁肃到柴桑见孙权。他先用“何不案兵束甲，北面而事之”相激，又分析曹军远来疲惫、不习水战，终于使孙权下决心派周瑜、程普率三万水军与刘备合力抗曹。'],
        ["Chaisang (now Jiujiang, Jiangxi)", "Wins Sun Quan to an alliance", "Volunteering as envoy, Zhuge Liang went with Lu Su to Sun Quan's camp at Chaisang. He challenged Sun Quan either to submit or to fight, and argued that Cao Cao's army was exhausted and unused to river warfare. Sun Quan resolved to resist and sent Zhou Yu and Cheng Pu with thirty thousand men to join Liu Bei."]),
      w(208, 113.67, 29.87,
        ['赤壁（今湖北赤壁）', '孙刘联军赤壁破曹', '周瑜的水军与刘备军会合后溯江而上，在赤壁以火攻大破曹军，曹操北还。《三国志》只说诸葛亮随东吴水军回到刘备军中、两军合力拒曹；“草船借箭”“借东风”等故事出自后世的小说《三国演义》。'],
        ["Red Cliffs (now Chibi, Hubei)", "The allies defeat Cao Cao at Red Cliffs", "Zhou Yu's fleet joined Liu Bei's troops, moved upriver and destroyed Cao Cao's fleet by fire at Red Cliffs, forcing him back north. The histories say only that Zhuge Liang returned with the Wu fleet to Liu Bei's camp; the tales of borrowing arrows with straw boats and summoning the east wind come from the later novel Romance of the Three Kingdoms."],
        { event: 'battle-of-red-cliffs' }),
      w(209, 112.6, 26.9,
        ['临烝（今湖南衡阳）', '任军师中郎将，督三郡赋税', '赤壁战后刘备收取荆州江南四郡，任命诸葛亮为军师中郎将，驻在临烝，督零陵、桂阳、长沙三郡，调集赋税以充军需。这是他第一次独当一面处理政务。'],
        ["Linzheng (now Hengyang, Hunan)", "Administers three commanderies of southern Jing", "After Red Cliffs Liu Bei took the four commanderies of Jing south of the Yangtze and made Zhuge Liang Military Adviser General of the Household. Based at Linzheng, he supervised Lingling, Guiyang and Changsha and gathered their taxes to supply the army, his first independent administrative charge."]),
      w(214, 104.07, 30.67,
        ['成都', '助刘备取益州', '刘备入蜀后与刘璋反目，军师庞统在雒城阵亡。留守荆州的诸葛亮与张飞、赵云率军溯江西上，分定沿途郡县，与刘备合围成都，刘璋出降。此后诸葛亮参与制定蜀地的法令《蜀科》。'],
        ["Chengdu", "Helps Liu Bei take Yi Province", "Liu Bei had entered Shu and fallen out with its governor Liu Zhang, and his adviser Pang Tong was killed at Luo. Zhuge Liang, left in charge in Jing, led Zhang Fei and Zhao Yun up the Yangtze, secured the commanderies on the way and joined the siege of Chengdu, where Liu Zhang surrendered. He then helped draft a law code for Shu."]),
      w(221, 104.07, 30.67,
        ['成都', '刘备称帝，拜为丞相', '曹丕代汉的消息传来，诸葛亮等劝刘备即帝位以延续汉祚。221年刘备在成都称帝，国号仍为汉，史称蜀汉，诸葛亮任丞相、录尚书事，总理国政。同年刘备东征孙吴，诸葛亮留守成都。'],
        ["Chengdu", "Becomes chancellor as Liu Bei takes the throne", "When news came that Cao Pi had ended the Han, Zhuge Liang and others urged Liu Bei to continue the dynasty. In 221 Liu Bei declared himself emperor at Chengdu of a state still called Han, known to history as Shu Han, with Zhuge Liang as chancellor. He stayed in Chengdu while Liu Bei marched east against Wu."]),
      w(223, 109.57, 31.04,
        ['永安宫（白帝城，今重庆奉节）', '白帝城托孤', '刘备在夷陵惨败于陆逊后退驻永安，病重时把诸葛亮从成都召来托付后事，说“若嗣子可辅，辅之；如其不才，君可自取”。诸葛亮流泪表示愿竭股肱之力，此后辅佐后主刘禅，蜀汉政事都由他决断。'],
        ["Yong'an Palace (Baidicheng, now Fengjie, Chongqing)", "Entrusted with the heir at Baidicheng", "After his crushing defeat by Lu Xun at Yiling, Liu Bei withdrew to Yong'an and, mortally ill, summoned Zhuge Liang from Chengdu. He entrusted his son Liu Shan to him, adding that if the heir proved unfit Zhuge Liang should take charge himself. Zhuge Liang pledged his loyalty in tears and thereafter directed the government of Shu."],
        { wiki: { zh: '白帝城', en: 'Baidicheng' } }),
      w(225, 103.8, 25.5,
        ['味县（今云南曲靖）', '南征平定南中', '南中豪强雍闿、孟获等乘刘备去世起兵。诸葛亮春天出兵，五月渡过泸水，分三路进军，秋天平定四郡，在滇池一带会师。他起用当地首领治理南中；“七擒孟获”之说见于东晋的《汉晋春秋》。'],
        ["Weixian (now Qujing, Yunnan)", "Pacifies the south", "Local leaders in Nanzhong, among them Yong Kai and Meng Huo, had risen after Liu Bei's death. Zhuge Liang set out in spring, crossed the Lu River in the fifth month and advanced in three columns, subduing the four commanderies by autumn. He left local chiefs in office; the story that he captured Meng Huo seven times comes from the later Han Jin Chunqiu."],
        { wiki: { zh: '诸葛亮南征', en: "Zhuge Liang's Southern Campaign" } }),
      w(227, 107.03, 33.07,
        ['汉中（今陕西汉中）', '上《出师表》，屯兵汉中准备北伐', '南方既定，诸葛亮率大军北驻汉中，临行向后主上《出师表》，劝他“亲贤臣，远小人”，并追述刘备三顾茅庐、临终托付的知遇之恩。此后七年，他以汉中为基地屡次出兵攻魏。'],
        ["Hanzhong (Shaanxi)", "Presents his memorial and moves to Hanzhong", "With the south secure, Zhuge Liang led the main army north to Hanzhong. Before leaving he presented the young emperor with the memorial known as the Chu Shi Biao, urging him to keep worthy ministers close and recalling the trust Liu Bei had placed in him. For the next seven years Hanzhong was his base against Wei."]),
      w(228, 105.4, 34.15,
        ['祁山（今甘肃礼县）', '首次北伐，街亭失守后退兵', '诸葛亮出祁山，陇右的天水、南安、安定三郡叛魏响应，关中震动。但前锋马谡在街亭违背部署，舍水上山，被魏将张郃击溃，蜀军被迫退回汉中。诸葛亮处死马谡，并上疏自贬三等。'],
        ["Mount Qi (Li County, Gansu)", "First northern campaign; retreat after Jieting", "Zhuge Liang advanced by Mount Qi, and three Wei commanderies west of the Long range came over to him. But his vanguard commander Ma Su ignored orders at Jieting, camped on a waterless hill and was routed by Zhang He, forcing a retreat to Hanzhong. Zhuge Liang had Ma Su executed and asked to be demoted three grades."],
        { wiki: { zh: '街亭之战', en: 'Battle of Jieting' } }),
      w(228, 107.14, 34.35,
        ['陈仓（今陕西宝鸡）', '出散关围陈仓，粮尽而还', '同年冬天，诸葛亮乘魏军主力东调对付孙吴，出散关包围陈仓。魏将郝昭以千余人坚守，蜀军用云梯、冲车、地道轮番攻城二十多天未能攻下，粮尽退兵，途中斩杀追来的魏将王双。'],
        ["Chencang (now Baoji, Shaanxi)", "Besieges Chencang and withdraws", "That winter, with Wei's main forces drawn east against Wu, Zhuge Liang came out through San Pass and besieged Chencang. Its commander Hao Zhao held out with little more than a thousand men against ladders, rams and tunnels for over twenty days, until Shu supplies ran out. On the retreat the pursuing Wei general Wang Shuang was killed."]),
      w(231, 105.4, 34.15,
        ['祁山', '再出祁山，以木牛运粮', '诸葛亮再次进攻祁山，用新造的“木牛”运送军粮，在卤城一带与司马懿对峙并取得小胜。后因李严督运的粮草不继而退兵，魏国名将张郃追到木门道，中箭身亡。'],
        ["Mount Qi", "Returns to Mount Qi with the 'wooden ox'", "Zhuge Liang attacked Mount Qi again, moving grain with a newly devised transport known as the wooden ox, and held his own against Sima Yi around Lucheng. When the supplies organised by Li Yan failed to arrive he withdrew; the veteran Wei general Zhang He pursued him to Mumen and was killed by an arrow."]),
      w(234, 107.63, 34.27,
        ['五丈原（今陕西岐山）', '最后一次北伐，病逝军中', '诸葛亮率大军出斜谷，在渭水南岸的五丈原扎营，并分兵屯田作长久之计。司马懿坚守不战，两军相持一百多天。这年八月，诸葛亮积劳成疾，病逝于军中，蜀军秘不发丧，整军退回汉中。'],
        ["Wuzhang Plains (Qishan County, Shaanxi)", "Dies in camp on his last campaign", "Zhuge Liang led his army out through the Xie valley and camped on the Wuzhang Plains south of the Wei River, setting soldiers to farm for a long stay. Sima Yi refused battle, and the two armies faced each other for over a hundred days. In the eighth month Zhuge Liang, worn out by overwork, died in camp, and the army withdrew in good order."],
        { wiki: { zh: '五丈原之战', en: 'Battle of Wuzhang Plains' } }),
      w(234, 106.62, 33.12,
        ['定军山（今陕西勉县）', '遗命葬于定军山', '按照遗嘱，诸葛亮葬在汉中定军山下，依山为坟，墓穴只容得下棺木，以平时的衣服入殓，不用陪葬器物。后主追谥他为忠武侯，后世因此称他“武侯”，今勉县有武侯墓。'],
        ["Mount Dingjun (Mian County, Shaanxi)", "Buried at Mount Dingjun as he had asked", "As his will directed, Zhuge Liang was buried at the foot of Mount Dingjun in Hanzhong, in a grave cut into the hillside just large enough for the coffin, dressed in everyday clothes and with no burial goods. He was given the posthumous title Marquis Zhongwu, and his tomb at Mian County is still visited."]),
    ],
    wiki: { zh: '诸葛亮', en: 'Zhuge Liang' },
  },
  {
    id: 'constantine', name: { zh: '君士坦丁大帝', en: 'Constantine the Great' }, birth: 272, death: 337, approx: true,
    title: { zh: '罗马皇帝', en: 'Roman emperor' }, region: 'europe', lineage: 'rome', sprite: 'crown',
    summary: {
      zh: '罗马帝国皇帝，史称“君士坦丁大帝”。306年他在约克被父亲的军队拥立，此后逐一击败对手，结束了四帝共治瓦解后的内战，于324年重新统一帝国。313年他与李锡尼在米兰商定宽容基督教（《米兰敕令》），325年召开尼西亚公会议。他将拜占庭扩建为新都君士坦丁堡，深刻影响了此后千年的欧洲历史。',
      en: "Roman emperor, known as Constantine the Great. Proclaimed by his father's army at York in 306, he fought his way through the civil wars that followed the breakdown of the Tetrarchy and by 324 had reunited the empire under his sole rule. With Licinius he agreed at Milan in 313 to tolerate Christianity, and in 325 he convened the First Council of Nicaea. He rebuilt Byzantium as a new capital, Constantinople, which remained the seat of the eastern empire for more than a thousand years.",
    },
    route: [
      w(272, 21.9, 43.32,
        ['奈苏斯（今塞尔维亚尼什）', '生于奈苏斯', '君士坦丁生于巴尔干的军事重镇奈苏斯，父亲君士坦提乌斯是伊利里亚出身的军官，母亲海伦娜出身低微。他的生年没有确切记载，一般认为在272年前后。'],
        ["Naissus (now Niš, Serbia)", "Born at Naissus", "Constantine was born in the Balkan garrison town of Naissus to Constantius, an army officer of Illyrian origin, and Helena, a woman of humble background. The year is not recorded; about 272 is the usual estimate."]),
      w(293, 29.92, 40.77,
        ['尼科米底亚（今土耳其伊兹米特）', '在戴克里先宫廷中成长', '293年父亲被立为西部的“凯撒”后，君士坦丁留在东部皇帝戴克里先的宫廷里，既受教育，也是人质。他随军到过多瑙河、叙利亚和埃及，303年在尼科米底亚目睹了对基督徒“大迫害”的开始。'],
        ["Nicomedia (now Izmit, Turkey)", "Raised at the court of Diocletian", "After his father became Caesar in the West in 293, Constantine was kept at the court of the eastern emperor Diocletian, part pupil and part hostage. He served on the Danube, in Syria and in Egypt, and was in Nicomedia in 303 when the Great Persecution of Christians began."]),
      w(305, 1.61, 50.73,
        ['博诺尼亚（今法国滨海布洛涅）', '西行投奔父亲', '305年戴克里先退位，父亲升任西部“奥古斯都”，君士坦丁却未被立为继承人。他获准离开东部皇帝伽列里乌斯的宫廷，日夜兼程横穿欧洲，在英吉利海峡边的博诺尼亚与父亲会合，一同渡海前往不列颠。'],
        ["Bononia (now Boulogne-sur-Mer, France)", "Rides west to join his father", "When Diocletian abdicated in 305 Constantius became Augustus in the West, but Constantine was passed over as heir. Allowed to leave the court of Galerius, he rode across Europe at speed and met his father at Bononia on the Channel coast, and together they crossed to Britain."]),
      w(306, -1.08, 53.96,
        ['埃布拉库姆（今英国约克）', '父亲去世，被军队拥立为帝', '父子二人北征皮克特人后回到约克，306年7月25日君士坦提乌斯在此病逝，军队当即拥立君士坦丁为“奥古斯都”。伽列里乌斯只承认他为“凯撒”，他由此控制了不列颠、高卢和西班牙。'],
        ["Eboracum (now York, England)", "Proclaimed emperor by his father's army", "Father and son campaigned against the Picts and returned to York, where Constantius died on 25 July 306. His troops at once hailed Constantine as Augustus. Galerius would recognise him only as Caesar, but Britain, Gaul and Spain were now in his hands."]),
      w(307, 6.64, 49.76,
        ['特里尔（奥古斯塔·特雷维罗鲁姆，今德国特里尔）', '以特里尔为都，经营高卢', '君士坦丁把宫廷设在摩泽尔河畔的特里尔，在这里住了约六年，多次渡过莱茵河进攻法兰克人。307年他娶前皇帝马克西米安之女法乌斯塔为妻，并在城中兴建浴场和宏大的觐见大殿。'],
        ["Trier (Augusta Treverorum, Germany)", "Rules Gaul from Trier", "Constantine set up his court at Trier on the Moselle and spent most of the next six years there, crossing the Rhine several times to fight the Franks. In 307 he married Fausta, daughter of the former emperor Maximian, and he embellished the city with baths and a great audience hall that still stands."],
        { via: [[-0.09, 51.51], [1.61, 50.73]], wiki: { zh: '君士坦丁巴西利卡', en: 'Aula Palatina' } }),
      w(310, 5.37, 43.3,
        ['马西利亚（今法国马赛）', '平定岳父马克西米安的叛乱', '已经退位的马克西米安趁君士坦丁在莱茵河作战，在阿尔勒夺取军队、自称皇帝。君士坦丁闻讯挥师沿罗讷河急速南下，把他围困在马西利亚，守军开城投降，马克西米安不久死去，据说是被迫自尽。'],
        ["Massilia (now Marseille, France)", "Puts down the revolt of Maximian", "While Constantine was fighting on the Rhine, his father-in-law Maximian seized troops at Arles and declared himself emperor again. Constantine hurried his army down the Rhone and trapped him in Massilia, whose garrison opened the gates. Maximian died soon afterwards, reportedly forced to take his own life."]),
      w(312, 7.69, 45.07,
        ['都灵（奥古斯塔·陶里诺鲁姆）', '翻越阿尔卑斯山，进军意大利', '312年春，君士坦丁率军翻越阿尔卑斯山，攻打占据意大利的马克森提乌斯。他先夺取山口下的苏萨，在都灵城外击溃敌方重装骑兵，都灵开城相迎，随后米兰也不战而降。'],
        ["Turin (Augusta Taurinorum, Italy)", "Crosses the Alps into Italy", "In spring 312 Constantine led his army over the Alps against Maxentius, who held Italy. He stormed Susa below the pass and broke the enemy's heavy cavalry outside Turin, which opened its gates to him, and Milan welcomed him soon afterwards."]),
      w(312, 10.99, 45.44,
        ['维罗纳（今意大利北部）', '围攻维罗纳，扫清北意大利', '马克森提乌斯在北方的主力由禁卫军长官鲁里基乌斯·庞培亚努斯率领，据守阿迪杰河环绕的坚城维罗纳。君士坦丁渡河围城，庞培亚努斯突围搬来援军，在城外一场延续到夜间的激战中兵败身亡。维罗纳开城后，阿奎莱亚等城相继归降。'],
        ["Verona (northern Italy)", "Takes Verona and secures northern Italy", "Maxentius's main northern army, under the praetorian prefect Ruricius Pompeianus, held Verona, a strong city in a loop of the Adige. Constantine crossed the river and laid siege; Pompeianus slipped out to fetch reinforcements and was defeated and killed in a battle that lasted into the night. Verona surrendered, and Aquileia and other cities followed."]),
      w(312, 12.47, 41.94,
        ['米尔维安桥（罗马城北）', '击败马克森提乌斯，入主罗马', '10月28日，两军在罗马城北台伯河上的米尔维安桥决战，马克森提乌斯兵败溺死。据基督教作家拉克坦提乌斯和优西比乌记载，君士坦丁战前见到异象，让士兵在盾牌上画上基督的符号。次日他进入罗马。'],
        ["Milvian Bridge (north of Rome)", "Defeats Maxentius and enters Rome", "On 28 October the armies met at the Milvian Bridge over the Tiber north of Rome; Maxentius was beaten and drowned in the river. The Christian writers Lactantius and Eusebius relate that Constantine, after a vision, had a sign of Christ marked on his soldiers' shields. He entered Rome the next day."],
        { wiki: { zh: '米尔维安大桥战役', en: 'Battle of the Milvian Bridge' } }),
      w(313, 9.19, 45.46,
        ['米兰（梅迪奥拉努姆）', '颁布《米兰敕令》，宽容基督教', '313年2月，君士坦丁与东部皇帝李锡尼在米兰会晤，把同父异母的妹妹君士坦提娅嫁给他。两人商定给予基督徒和一切人信仰自由，并归还被没收的教会财产，这项后来由李锡尼在东部公布的政策习称《米兰敕令》。'],
        ["Milan (Mediolanum)", "Agrees the 'Edict of Milan'", "In February 313 Constantine met the eastern emperor Licinius at Milan and gave him his half-sister Constantia in marriage. The two agreed to grant Christians and all others freedom of worship and to restore confiscated church property, a policy later published by Licinius in the East and known as the Edict of Milan."],
        { event: 'edict-of-milan' }),
      w(315, 12.4906, 41.8898,
        ['罗马', '君士坦丁凯旋门落成', '315年君士坦丁回到罗马庆祝即位十周年，元老院为纪念米尔维安桥之战而建的凯旋门在斗兽场旁落成，门上有不少从前代皇帝纪念建筑上移来的浮雕。在罗马，他还出资兴建了拉特朗大殿。'],
        ["Rome", "The Arch of Constantine is dedicated", "Constantine returned to Rome in 315 to celebrate ten years of rule. The triumphal arch voted by the Senate for his victory at the Milvian Bridge was dedicated beside the Colosseum, decorated in part with reliefs taken from monuments of earlier emperors. In Rome he also paid for the Lateran Basilica."],
        { wiki: { zh: '君士坦丁凯旋门', en: 'Arch of Constantine' } }),
      w(316, 18.8, 45.29,
        ['基巴莱（今克罗地亚温科夫齐）', '与李锡尼初次交战', '两位皇帝的同盟破裂，君士坦丁在潘诺尼亚的基巴莱击败李锡尼（一说在314年），随后又在色雷斯交战。317年双方在塞尔迪卡（今索非亚）议和，李锡尼让出色雷斯以外的巴尔干各省，君士坦丁此后常驻塞尔迪卡和西尔米乌姆。'],
        ["Cibalae (now Vinkovci, Croatia)", "First war with Licinius", "The alliance of the two emperors broke down, and Constantine beat Licinius at Cibalae in Pannonia (some date it to 314) and fought him again in Thrace. Peace made at Serdica, now Sofia, in 317 gave Constantine all the Balkan provinces except Thrace, and he spent much of the next years at Serdica and Sirmium."],
        { via: [[12.57, 44.06], [11.88, 45.41], [13.37, 45.77]] }),
      w(324, 26.56, 41.68,
        ['哈德良堡（今土耳其埃迪尔内）', '哈德良堡之战击败李锡尼', '324年战端再起，7月3日君士坦丁强渡赫布鲁斯河，在哈德良堡大败李锡尼，本人也在战斗中负伤。李锡尼退守拜占庭，君士坦丁的长子克里斯普斯又在赫勒斯滂海峡歼灭了他的舰队。'],
        ["Adrianople (now Edirne, Turkey)", "Defeats Licinius at Adrianople", "War resumed in 324. On 3 July Constantine forced a crossing of the Hebrus and routed Licinius at Adrianople, being wounded himself in the fighting. Licinius fell back on Byzantium, and Constantine's eldest son Crispus destroyed his fleet in the Hellespont."]),
      w(324, 29.03, 41.02,
        ['克里索波利斯（今伊斯坦布尔于斯屈达尔）', '击败李锡尼，重新统一罗马帝国', '李锡尼渡海退到博斯普鲁斯海峡亚洲一岸，9月18日在克里索波利斯再次战败，不久在尼科米底亚投降，次年被处死。自戴克里先分治以来近四十年，罗马帝国重新由一位皇帝统治。'],
        ["Chrysopolis (now Üsküdar, Istanbul)", "Reunites the empire", "Licinius crossed to the Asian shore of the Bosporus and on 18 September was beaten again at Chrysopolis. He surrendered at Nicomedia and was put to death the following year. For the first time since Diocletian divided power nearly forty years earlier, the Roman Empire had a single ruler."]),
      w(325, 29.72, 40.43,
        ['尼西亚（今土耳其伊兹尼克）', '召开第一次尼西亚公会议', '为平息亚历山大城司铎阿里乌引起的教义之争，君士坦丁召集帝国各地约三百名主教到尼西亚开会，并亲自到场致辞。会议制定《尼西亚信经》，确认圣子与圣父“同质”，还统一了复活节的推算方法。'],
        ["Nicaea (now Iznik, Turkey)", "Convenes the First Council of Nicaea", "To settle the dispute stirred up by the Alexandrian priest Arius, Constantine summoned about three hundred bishops from across the empire to Nicaea and addressed them in person. The council produced the Nicene Creed, declaring the Son 'of one substance' with the Father, and agreed a common reckoning of Easter."],
        { wiki: { zh: '第一次尼西亚公会议', en: 'First Council of Nicaea' } }),
      w(326, 12.4823, 41.8933,
        ['罗马', '最后一次到罗马', '君士坦丁到罗马庆祝即位二十周年，这是他最后一次踏足这座城市。同年，他下令处死长子克里斯普斯，不久皇后法乌斯塔也死去，原因至今不明。他的母亲海伦娜随后前往巴勒斯坦朝圣。'],
        ["Rome", "His last visit to Rome", "Constantine came to Rome to celebrate twenty years of rule; he never saw the city again. In the same year he ordered the execution of his eldest son Crispus, and soon afterwards his wife Fausta also died, for reasons that remain obscure. His mother Helena then left on a pilgrimage to Palestine."],
        { via: [[28.98, 41.01], [23.32, 42.7], [19.61, 44.97], [13.37, 45.77], [11.88, 45.41], [12.57, 44.06]] }),
      w(328, 24.47, 43.71,
        ['奥埃斯库斯（今保加利亚吉根）', '在多瑙河上架桥', '328年，君士坦丁在奥埃斯库斯与对岸的苏基达瓦之间建成一座横跨多瑙河的大桥，全长两千多米，以便出兵河北。此后他在332年击败哥特人，334年又击败萨尔马提亚人，重建了多瑙河防线。'],
        ["Oescus (now Gigen, Bulgaria)", "Bridges the Danube", "In 328 Constantine opened a bridge across the Danube between Oescus and Sucidava on the north bank, well over two kilometres long, to carry his armies beyond the river. He went on to defeat the Goths in 332 and the Sarmatians in 334, restoring the Danube frontier."],
        { via: [[12.57, 44.06], [11.88, 45.41], [13.37, 45.77], [19.61, 44.97]] }),
      w(330, 28.98, 41.01,
        ['君士坦丁堡（今伊斯坦布尔）', '新都落成', '击败李锡尼后，君士坦丁选中扼守博斯普鲁斯海峡的古城拜占庭营建新都，扩建城墙、宫殿、广场和赛车场。330年5月11日新都举行落成典礼，后以他的名字称为君士坦丁堡。'],
        ["Constantinople (now Istanbul)", "Dedicates his new capital", "After defeating Licinius, Constantine chose the old city of Byzantium, commanding the Bosporus, for a new capital and enlarged it with walls, a palace, a forum and a hippodrome. It was dedicated on 11 May 330 and came to be called Constantinople after him."],
        { event: 'founding-of-constantinople' }),
      w(337, 29.92, 40.77,
        ['尼科米底亚（今土耳其伊兹米特）', '临终受洗，病逝', '337年君士坦丁准备东征波斯，途中病倒，在尼科米底亚城郊由主教优西比乌施洗，5月22日去世。他是第一位受洗的罗马皇帝，遗体运回君士坦丁堡，葬在他所建的圣使徒教堂。'],
        ["Nicomedia (now Izmit, Turkey)", "Baptised on his deathbed", "In 337, preparing a campaign against Persia, Constantine fell ill on the road. He was baptised near Nicomedia by its bishop Eusebius and died on 22 May, the first Roman emperor to receive baptism. His body was carried back to Constantinople and buried in the Church of the Holy Apostles, which he had founded."]),
    ],
    wiki: { zh: '君士坦丁大帝', en: 'Constantine the Great' },
  },
  {
    id: 'muhammad', name: { zh: '穆罕默德', en: 'Muhammad' }, birth: 570, death: 632, approx: true,
    title: { zh: '伊斯兰教先知、创立者', en: 'Prophet and founder of Islam' }, region: 'west-asia', lineage: 'arab', sprite: 'camel',
    summary: {
      zh: '伊斯兰教的创立者，穆斯林尊为先知，生于阿拉伯半岛的麦加。据伊斯兰传统，他约四十岁时开始接受启示并传教，622年迁往麦地那建立穆斯林社团，630年返回麦加。至632年去世时，阿拉伯半岛大部已统一于伊斯兰旗帜之下，其继承者随后建立起庞大的阿拉伯帝国。',
      en: "Founder of Islam, revered by Muslims as the Prophet, born in Mecca in western Arabia. According to Islamic tradition he began to receive revelations at about the age of forty and to preach the worship of one God. In 622 he moved with his followers to Medina, where the first Muslim community took shape, and in 630 he returned to Mecca. By his death in 632 most of the Arabian Peninsula had accepted Islam, and his successors went on to build a vast Arab empire.",
    },
    route: [
      w(570, 39.826, 21.4225,
        ['麦加（今沙特阿拉伯）', '生于古莱什部落哈希姆家族', '穆罕默德生于商业城镇麦加，属古莱什部落的哈希姆家族，传统上把他的生年定在570年前后。父亲阿卜杜拉在他出生前去世，六岁时母亲阿米娜也去世，他先后由祖父阿卜杜勒·穆塔里布和伯父艾布·塔里布抚养。'],
        ["Mecca (Saudi Arabia)", "Born into the Hashim clan of the Quraysh", "Muhammad was born in the trading town of Mecca into the Hashim clan of the Quraysh tribe; tradition places the year about 570. His father Abdullah died before his birth and his mother Amina when he was six, and he was brought up first by his grandfather Abd al-Muttalib and then by his uncle Abu Talib."],
        { wiki: { zh: '克尔白', en: 'Kaaba' } }),
      w(582, 36.48, 32.52,
        ['布斯拉（今叙利亚南部）', '少年时随伯父的商队到叙利亚', '据伊斯兰传统，穆罕默德十二岁左右随伯父艾布·塔里布的商队北上叙利亚。相传在布斯拉，一位名叫巴希拉的基督教修士认出这个少年将成为先知。成年后他以经商为业，因诚实被称为“艾敏”（可信者）。'],
        ["Bosra (southern Syria)", "Travels to Syria with his uncle's caravan", "Islamic tradition relates that at about twelve Muhammad went north to Syria with the caravan of his uncle Abu Talib, and that at Bosra a Christian monk named Bahira recognised the boy as a future prophet. As a young man he worked in the caravan trade and was known for his honesty as al-Amin, 'the trustworthy'."]),
      w(595, 39.826, 21.4225,
        ['麦加', '与赫蒂彻成婚', '穆罕默德受雇为富孀赫蒂彻经营前往叙利亚的商队，约二十五岁时与她成婚。两人共同生活了二十多年，育有法蒂玛等子女，赫蒂彻在世时他没有另娶，她后来也是第一个相信他所受启示的人。'],
        ["Mecca", "Marries Khadija", "Muhammad managed a caravan to Syria for Khadija, a wealthy widow, and married her when he was about twenty-five. They lived together for more than twenty years and had several children, among them Fatima; he took no other wife while she lived, and she was later the first to believe in his revelations."]),
      w(610, 39.8579, 21.4576,
        ['希拉山洞（麦加城郊光明山）', '据伊斯兰传统，在此首次接受启示', '穆罕默德常到麦加城外的希拉山洞独自静思。据伊斯兰传统，约610年斋月的一个夜晚，天使吉卜利勒在洞中向他显现，命他“你当诵读”，这便是《古兰经》最早降示的经文。'],
        ["Cave of Hira (Jabal al-Nour, outside Mecca)", "Receives the first revelation, by Islamic tradition", "Muhammad used to withdraw for solitary reflection to the cave of Hira on a hill outside Mecca. According to Islamic tradition, on a night in Ramadan about 610 the angel Gabriel appeared to him there and commanded him to 'Recite', the first words of the Quran to be revealed."],
        { wiki: { zh: '希拉山洞', en: 'Cave of Hira' } }),
      w(613, 39.826, 21.4225,
        ['麦加', '开始公开传教', '最初几年穆罕默德只在亲友中传教，约613年起公开宣讲独一的真主和末日审判，反对偶像崇拜，触动了以克尔白朝圣获利的古莱什贵族。信徒屡受迫害，约615年一部分人渡过红海，到阿比西尼亚（今埃塞俄比亚）避难。'],
        ["Mecca", "Begins to preach in public", "After some years of teaching only among family and friends, Muhammad began about 613 to preach openly of one God and a day of judgement and to denounce idols, alarming the Quraysh leaders who profited from pilgrimage to the Kaaba. His followers were harassed, and about 615 some took refuge across the Red Sea in Abyssinia."]),
      w(619, 40.4158, 21.2703,
        ['塔伊夫（麦加东南）', '赴塔伊夫求助遭拒', '约619年，妻子赫蒂彻和一直庇护他的伯父艾布·塔里布相继去世，后世称为“悲伤之年”。失去家族保护的穆罕默德前往麦加东南的山城塔伊夫，希望得到塞基夫部落的支持，却被拒绝并被人掷石驱逐，只得返回麦加。'],
        ["Ta'if (south-east of Mecca)", "Seeks support at Ta'if and is turned away", "About 619 his wife Khadija and his protector Abu Talib died within a short time, remembered as the Year of Sorrow. Without his clan's protection, Muhammad went to the hill town of Ta'if to seek the backing of the Thaqif tribe, but was rejected, pelted with stones and forced to return to Mecca."]),
      w(622, 39.85, 21.377,
        ['骚尔山洞（麦加以南）', '离开麦加，藏身骚尔山洞', '叶斯里卜的居民邀请穆罕默德前去调解部落纷争，并在阿格白立誓保护他，信徒于是分批北迁。622年古莱什人密谋行刺，穆罕默德与艾布·伯克尔连夜出城，据传统记载先在城南的骚尔山洞中躲了三天，才绕道北上。'],
        ["Cave of Thawr (south of Mecca)", "Leaves Mecca and hides in the cave of Thawr", "The people of Yathrib had invited Muhammad to arbitrate their feuds and pledged at Aqaba to protect him, and his followers moved north in small groups. In 622, as the Quraysh plotted to kill him, he slipped away by night with Abu Bakr; tradition says they hid for three days in a cave on Mount Thawr before turning north."]),
      w(622, 39.61, 24.47,
        ['麦地那（原名叶斯里卜）', '迁徙麦地那（希吉拉）', '穆罕默德先到城南的库巴，在那里建起第一座清真寺，随后进入叶斯里卜，这座城后来称为“麦地那”，意为“先知之城”。他在此修建清真寺和住所，订立约章，把迁士、辅士和当地各部落结成一个社团。这一年后来被定为伊斯兰历元年。'],
        ["Medina (formerly Yathrib)", "The Hijrah to Medina", "Muhammad stopped first at Quba, south of the town, where the first mosque was built, and then entered Yathrib, later called Medina, 'the city of the Prophet'. He built a mosque and house and drew up a charter binding the emigrants, their local helpers and the town's tribes into one community. The year became year one of the Islamic calendar."],
        { event: 'hijrah' }),
      w(624, 38.78, 23.73,
        ['白德尔（麦地那西南）', '白德尔之战获胜', '624年3月，穆罕默德率三百多人到白德尔水井附近拦截一支从叙利亚返回的麦加商队，与前来救援、人数约为其三倍的古莱什军队交战并获胜。这是穆斯林的第一场大胜，《古兰经》中也提到此役。'],
        ["Badr (south-west of Medina)", "Victory at Badr", "In March 624 Muhammad led a little over three hundred men to the wells of Badr to intercept a Meccan caravan returning from Syria, and defeated the Quraysh relief force of about three times their number. It was the Muslims' first major victory and is mentioned in the Quran."],
        { wiki: { zh: '白德尔之战', en: 'Battle of Badr' } }),
      w(625, 39.6117, 24.5028,
        ['武侯德山（麦地那城北）', '武侯德之战受挫', '次年古莱什人率约三千人前来报复，两军在麦地那城北的武侯德山下交战。穆斯林起初占优，但把守山口的弓箭手擅离阵地，被哈立德·本·瓦利德的骑兵从背后突袭，穆罕默德本人负伤，叔父哈姆扎阵亡。'],
        ["Mount Uhud (north of Medina)", "Setback at Uhud", "The next year the Quraysh returned with about three thousand men, and the armies met below Mount Uhud north of Medina. The Muslims had the upper hand until their archers left a key position and Khalid ibn al-Walid's cavalry struck from behind. Muhammad was wounded and his uncle Hamza was killed."]),
      w(627, 39.61, 24.47,
        ['麦地那', '壕沟之战守住麦地那', '627年古莱什人联合多个部落围攻麦地那，传统上说兵力约有一万人。穆罕默德采纳波斯人萨勒曼的建议，在城北无险可守的一面挖掘壕沟，联军骑兵无法越过，围城数周后因寒风和内部不和而撤退。'],
        ["Medina", "Holds Medina at the Battle of the Trench", "In 627 the Quraysh and their allied tribes, some ten thousand men by tradition, laid siege to Medina. On the advice of Salman the Persian, Muhammad had a trench dug across the open northern approach, which the attackers' cavalry could not cross. After several weeks of cold winds and quarrels the coalition withdrew."]),
      w(628, 39.62, 21.44,
        ['侯代比亚（麦加以西）', '订立侯代比亚和约', '628年穆罕默德率约一千四百名信徒前往麦加朝觐，在城西的侯代比亚被古莱什人阻拦。双方议定休战十年，穆斯林当年返回，次年可入城朝觐三天。和约使他得以腾出手来争取其他部落、扩大影响。'],
        ["Hudaybiyyah (west of Mecca)", "Concludes the Treaty of Hudaybiyyah", "In 628 Muhammad set out with about fourteen hundred followers to make the pilgrimage to Mecca and was stopped at Hudaybiyyah, west of the city. The two sides agreed a ten-year truce: the Muslims would turn back that year and be admitted for three days the next. The peace freed him to win over other tribes."]),
      w(628, 39.29, 25.7,
        ['海拜尔（麦地那以北）', '远征海拜尔绿洲', '和约订立后不久，穆罕默德率军北上，攻打麦地那以北约150公里的海拜尔绿洲，那里的犹太部落曾支持围攻麦地那的联军。各座堡垒相继陷落后，居民获准留下耕种，每年交纳一半收成。'],
        ["Khaybar (north of Medina)", "Expedition to the oasis of Khaybar", "Soon after the truce Muhammad marched north against Khaybar, an oasis about 150 km from Medina whose Jewish tribes had backed the coalition that besieged the city. When its forts had fallen one by one, the inhabitants were allowed to stay and farm in return for half of each year's harvest."]),
      w(630, 39.826, 21.4225,
        ['麦加', '率军进入麦加', '古莱什的盟友违反和约后，穆罕默德于630年1月率约一万人进军麦加，几乎未遇抵抗就进了城。他宣布赦免城中居民，清除克尔白内外的偶像。不久他又在侯奈因击败哈瓦津部落，并围攻塔伊夫。'],
        ["Mecca", "Enters Mecca at the head of his army", "After allies of the Quraysh broke the truce, Muhammad marched on Mecca in January 630 with about ten thousand men and entered almost unopposed. He declared an amnesty for its people and had the idols in and around the Kaaba removed. Soon afterwards he defeated the Hawazin tribes at Hunayn and besieged Ta'if."],
        { wiki: { zh: '征服麦加', en: 'Conquest of Mecca' } }),
      w(630, 36.57, 28.38,
        ['塔布克（阿拉伯半岛西北）', '北征塔布克', '630年秋，传闻拜占庭军队在边境集结，穆罕默德在酷暑中率大军北上到塔布克，这是他一生中到达的最北处之一。敌军没有出现，他与艾莱（今亚喀巴）等地的首领订立了纳贡条约后返回。'],
        ["Tabuk (north-west Arabia)", "Leads an expedition north to Tabuk", "In autumn 630, on reports that Byzantine forces were gathering on the frontier, Muhammad led a large army north in fierce heat to Tabuk, far beyond any of his earlier campaigns. No enemy appeared, and he returned after making tribute agreements with the rulers of Ayla, now Aqaba, and other border towns."]),
      w(632, 39.984, 21.355,
        ['阿拉法特山（麦加以东）', '辞别朝觐', '632年3月，穆罕默德率众信徒到麦加完成他唯一的一次正朝，史称“辞朝”，朝觐的各项仪式由此确立。他在阿拉法特山发表演说，强调穆斯林彼此皆为兄弟，生命和财产不可侵犯。'],
        ["Mount Arafat (east of Mecca)", "The Farewell Pilgrimage", "In March 632 Muhammad led a great company of believers on his only full pilgrimage to Mecca, later called the Farewell Pilgrimage, which fixed the rites of the hajj. At Mount Arafat he gave a sermon stressing that Muslims are brothers to one another and that life and property are inviolable."],
        { wiki: { zh: '阿拉法特山', en: 'Mount Arafat' } }),
      w(632, 39.61, 24.47,
        ['麦地那', '完成辞别朝觐后病逝', '回到麦地那后不久，穆罕默德病倒，632年6月8日在妻子阿伊莎的房中去世，就地安葬，这里如今在先知清真寺内。众人推举艾布·伯克尔为第一任哈里发；也有人认为继承者应是他的堂弟兼女婿阿里，这一分歧日后演变为逊尼派与什叶派的分野。'],
        ["Medina", "Dies soon after the Farewell Pilgrimage", "Soon after returning to Medina Muhammad fell ill, and he died on 8 June 632 in the room of his wife Aisha, where he was buried; the spot now lies within the Prophet's Mosque. Abu Bakr was chosen as the first caliph, while others held that Ali, his cousin and son-in-law, was the rightful successor, a dispute from which the Sunni-Shia division later grew."],
        { wiki: { zh: '先知寺', en: "Prophet's Mosque" } }),
    ],
    wiki: { zh: '穆罕默德', en: 'Muhammad' },
  },
  {
    id: 'tang-taizong', name: { zh: '唐太宗', en: 'Emperor Taizong of Tang' }, birth: 598, death: 649,
    title: { zh: '唐朝皇帝', en: 'Emperor of the Tang dynasty' }, region: 'china', lineage: 'china', sprite: 'horse',
    summary: {
      zh: '唐朝第二位皇帝李世民。他随父起兵，为唐朝统一天下立有大功，626年发动玄武门之变后即位。在位期间任用房玄龄、杜如晦、魏征等贤臣，虚心纳谏、轻徭薄赋，击灭东突厥，被西北各族尊为“天可汗”。他在位的贞观年间被后世视为治世的典范，史称“贞观之治”。',
      en: "Li Shimin, second emperor of the Tang dynasty. As a young commander he won many of the battles by which his father's new dynasty reunified China, and in 626 he took the throne after the coup at the Xuanwu Gate. Served by ministers such as Fang Xuanling, Du Ruhui and Wei Zheng, he was known for heeding criticism and lightening taxes and labour service. His armies destroyed the Eastern Turkic khaganate, and the peoples of the north-west hailed him as 'Heavenly Khagan'. His Zhenguan era was long held up as a model of good government.",
    },
    route: [
      w(598, 108.2, 34.26,
        ['武功（今陕西武功）', '生于隋朝武功别馆', '李世民是唐国公李渊的次子，母亲窦氏，出身北周以来的关陇贵族之家，生于渭水北岸武功的李家别馆。他少年时习骑射，后娶长孙氏为妻。隋炀帝末年天下大乱，他随父亲在太原任上。'],
        ["Wugong (Shaanxi)", "Born at the family villa in Wugong", "Li Shimin was the second son of Li Yuan, Duke of Tang, and Lady Dou, of the north-western aristocracy that had dominated since Northern Zhou times; he was born at the family's country house at Wugong, north of the Wei River. Trained in riding and archery, he was with his father at Taiyuan as the Sui empire fell into chaos."]),
      w(617, 112.55, 37.87,
        ['晋阳（今山西太原）', '随父李渊在太原起兵', '617年各地起事不断，隋朝濒于瓦解，太原留守李渊在晋阳起兵。年轻的李世民参与密谋、招募兵士，随后与兄长李建成率军攻取西河郡，为大军南下打开通路。'],
        ["Jinyang (now Taiyuan, Shanxi)", "Joins his father's rising at Taiyuan", "In 617, as rebellions tore the Sui empire apart, Li Yuan, the garrison commander at Taiyuan, rose in arms at Jinyang. The young Li Shimin helped plan the rising and raise troops, then with his elder brother Li Jiancheng took Xihe commandery, opening the road south."]),
      w(617, 111.72, 36.57,
        ['霍邑（今山西霍州）', '霍邑之战击败宋老生', '李渊军南下，被隋将宋老生阻于霍邑，又逢连日大雨、军粮将尽，李渊一度打算退回太原。李世民力谏不可，雨停后唐军诱敌出城，他率骑兵从南原冲击隋军侧背，阵斩宋老生，进军关中之路由此打通。'],
        ["Huoyi (now Huozhou, Shanxi)", "Defeats Song Laosheng at Huoyi", "Marching south, Li Yuan was held up at Huoyi by the Sui general Song Laosheng, and with days of rain and grain running short he considered turning back. Li Shimin argued him out of it. When the weather cleared the Sui force was lured out of the town, and Li Shimin's cavalry charge from the south broke it, opening the way to Guanzhong."]),
      w(618, 108.94, 34.34,
        ['长安（今陕西西安）', '唐朝建立，受封秦王', '李渊军渡过黄河，617年冬攻克长安，先立隋代王杨侑为帝。618年隋炀帝在江都被杀，李渊在长安称帝，建立唐朝，李世民受封秦王、任尚书令，此后数年一直领兵在外征战。'],
        ["Chang'an (now Xi'an, Shaanxi)", "The Tang is founded; he becomes Prince of Qin", "Li Yuan's army crossed the Yellow River and took Chang'an in the winter of 617, at first setting a Sui prince on the throne. When Emperor Yang was killed at Jiangdu in 618, Li Yuan proclaimed himself emperor of a new dynasty, Tang. Li Shimin was made Prince of Qin and spent the next years in the field."],
        { event: 'tang-founding' }),
      w(618, 107.8, 35.2,
        ['浅水原（今陕西长武）', '浅水原之战平定薛仁杲', '割据陇右的薛举进逼长安，唐军先在浅水原大败，其时李世民正卧病军中。薛举死后，李世民再度领兵，坚壁不战六十余日，待敌军粮尽、将士离心后出击，一战击溃，薛仁杲出降，陇右平定。'],
        ["Qianshuiyuan (now Changwu, Shaanxi)", "Destroys the Xue regime at Qianshuiyuan", "Xue Ju, who held the lands west of the Long range, threatened Chang'an and beat a Tang army at Qianshuiyuan while Li Shimin lay ill. After Xue Ju died Li Shimin took command again, refused battle for some sixty days until the enemy ran short of food, then attacked and routed them. Xue Rengao surrendered, and the north-west was secure."]),
      w(620, 111.22, 35.62,
        ['柏壁（今山西新绛）', '击败刘武周、宋金刚，收复太原', '刘武周在突厥支持下南下，攻占太原和河东大部。李世民踏冰渡过黄河，屯兵柏壁与宋金刚相持数月，断其粮道，待其退兵时一昼夜追击二百余里，在介休一带将其击溃，并州全境收复。'],
        ["Bobi (now Xinjiang County, Shanxi)", "Defeats Liu Wuzhou and recovers Taiyuan", "Backed by the Turks, Liu Wuzhou had overrun Taiyuan and most of Hedong. Li Shimin crossed the frozen Yellow River, faced the enemy general Song Jingang at Bobi for months while cutting his supply lines, and when Song withdrew pursued him without rest as far as Jiexiu and destroyed his army. All of Bingzhou was recovered."]),
      w(621, 113.2, 34.8,
        ['虎牢关（今河南荥阳汜水镇）', '虎牢之战擒窦建德，迫降王世充', '唐军围攻洛阳的王世充，河北的窦建德率十余万人来援。李世民亲率三千五百精兵东进，据守虎牢，拖到敌军列阵半日、士卒饥渴疲惫时突然出击，生擒窦建德。王世充随即开城投降，中原大势已定。'],
        ["Hulao Pass (Sishui, Xingyang, Henan)", "Captures Dou Jiande at Hulao", "While Tang forces besieged Wang Shichong in Luoyang, Dou Jiande of Hebei marched to relieve him with a much larger army. Li Shimin took 3,500 picked men east to hold Hulao, waited until the enemy had stood in line for half a day, hungry and thirsty, then charged and captured Dou Jiande. Wang Shichong surrendered Luoyang soon after."],
        { wiki: { zh: '虎牢之战', en: 'Battle of Hulao' } }),
      w(626, 108.94, 34.34,
        ['长安', '发动玄武门之变，继位为帝', '李世民功高望重，与太子李建成、齐王李元吉的矛盾日益激化。626年7月2日，他在宫城北面的玄武门设伏，亲手射杀李建成，部将杀死李元吉。两个月后，唐高祖李渊让位，李世民即位，次年改元贞观。'],
        ["Chang'an", "Seizes power at the Xuanwu Gate", "Li Shimin's prestige had set him against his elder brother, the crown prince Li Jiancheng, and their brother Li Yuanji. On 2 July 626 he ambushed them at the Xuanwu Gate on the north side of the palace, shooting Li Jiancheng himself while his officers killed Li Yuanji. Two months later Emperor Gaozu abdicated in his favour."],
        { wiki: { zh: '玄武门之变', en: 'Xuanwu Gate Incident' } }),
      w(626, 108.75, 34.36,
        ['渭水便桥（今陕西咸阳一带）', '渭水之盟', '李世民即位不到一个月，东突厥颉利可汗率大军直抵长安城外的渭水北岸。他带着几名大臣骑马来到便桥，隔水责备颉利背约，随后唐军大队赶到。两天后双方在桥上杀白马结盟，突厥退兵。'],
        ["Bian Bridge on the Wei River (near Xianyang, Shaanxi)", "The alliance of the Wei River", "Less than a month after his accession, the Eastern Turkic ruler Illig Qaghan brought a great army to the north bank of the Wei, just outside Chang'an. Taizong rode to the Bian Bridge with a handful of ministers and reproached the qaghan across the water as his troops came up behind. Two days later they sacrificed a white horse and the Turks withdrew."]),
      w(630, 108.94, 34.34,
        ['长安', '击灭东突厥，被尊为“天可汗”', '629年冬，唐太宗乘东突厥内乱、连年雪灾，派李靖、李勣等分路北伐。次年初李靖夜袭定襄，又在阴山大破突厥，颉利可汗被俘送到长安。西北各族君长入朝，共上尊号“天可汗”。'],
        ["Chang'an", "Destroys the Eastern Turks; hailed as Heavenly Khagan", "In the winter of 629, with the Eastern Turks weakened by revolt and harsh winters, Taizong sent Li Jing, Li Shiji and others north in several columns. Li Jing raided Dingxiang by night and crushed the Turks at the Yin Mountains early in 630, and Illig Qaghan was brought captive to Chang'an. The rulers of the north-western peoples offered Taizong the title Heavenly Khagan."],
        { wiki: { zh: '唐灭东突厥之战', en: 'Tang campaign against the Eastern Turks' } }),
      w(632, 107.79, 34.68,
        ['九成宫（今陕西麟游）', '九成宫避暑，发现醴泉', '九成宫原是隋朝的仁寿宫，在长安西北的山中，太宗多次到这里避暑。632年夏他在宫中散步时发现一处泉水，以为祥瑞，命魏征撰文、欧阳询书写，刻成《九成宫醴泉铭》碑，后世奉为楷书的典范。'],
        ["Jiucheng Palace (Linyou, Shaanxi)", "Summers at Jiucheng Palace", "Jiucheng Palace, the former Renshou Palace of the Sui, lay in the hills north-west of Chang'an, and Taizong often spent the summer there. In 632 he came upon a spring in the grounds and took it as an auspicious sign. Wei Zheng composed a text and Ouyang Xun wrote it out for a stele, long treated as a model of regular-script calligraphy."]),
      w(641, 108.94, 34.34,
        ['长安', '文成公主入藏和亲', '640年唐军攻灭高昌，设安西都护府，同年吐蕃赞普松赞干布派大相禄东赞到长安请婚。641年太宗以宗室女文成公主出嫁吐蕃，由江夏王李道宗护送。阎立本的《步辇图》相传画的就是太宗接见禄东赞的情景。'],
        ["Chang'an", "Princess Wencheng is sent to Tibet", "In 640 Tang armies conquered Gaochang and set up the Anxi Protectorate, and the Tibetan ruler Songtsen Gampo sent his minister Gar Tongtsen to Chang'an to ask for a bride. In 641 Taizong sent Princess Wencheng, a lady of the imperial clan, to Tibet. A painting attributed to Yan Liben shows Taizong receiving the Tibetan envoy."],
        { wiki: { zh: '步辇图', en: 'Emperor Taizong Receiving the Tibetan Envoy' } }),
      w(645, 123.17, 41.27,
        ['辽东城（今辽宁辽阳）', '亲征高句丽', '太宗以高句丽权臣渊盖苏文弑君为由亲征。645年春他从洛阳出发，经定州、幽州渡过辽水，五月唐军借南风纵火攻克辽东城，随后又取白岩城。'],
        ["Liaodong (now Liaoyang, Liaoning)", "Leads the campaign against Goguryeo", "Citing the murder of the Goguryeo king by the strongman Yeon Gaesomun, Taizong took the field in person. He set out from Luoyang in spring 645, passed through Dingzhou and Youzhou and crossed the Liao River; in the fifth month his army stormed the fortress of Liaodong and then took Baiyan."]),
      w(645, 122.8, 40.8,
        ['安市城（今辽宁海城一带）', '久攻安市不下，班师', '唐军在安市城外击溃高句丽援军，却始终攻不下这座山城，围攻近三个月，筑起的土山也被守军夺去。九月辽东天寒，粮草将尽，太宗下令撤军。归途中他在幽州下令建悯忠寺追悼阵亡将士，即今北京法源寺的前身。'],
        ["Ansi (near Haicheng, Liaoning)", "Fails before Ansi and withdraws", "The Tang army routed a Goguryeo relief force outside Ansi but in nearly three months could not take the hill fortress itself, and even its great siege ramp was seized by the defenders. With winter coming and supplies low, Taizong ordered a retreat. At Youzhou he ordered a temple for the fallen, the forerunner of Beijing's Fayuan Temple."],
        { wiki: { zh: '安市城之战', en: 'Siege of Ansi' } }),
      w(649, 108.95, 34.05,
        ['翠微宫（长安城南终南山）', '病逝于翠微宫', '太宗晚年多病，又服食方士所炼丹药。649年他到终南山的翠微宫养病，7月10日在含风殿去世，临终把太子李治托付给长孙无忌和褚遂良。'],
        ["Cuiwei Palace (Zhongnan Mountains, south of Chang'an)", "Dies at Cuiwei Palace", "In poor health in his last years, Taizong also took elixirs prepared by alchemists. In 649 he went to convalesce at Cuiwei Palace in the Zhongnan Mountains and died there on 10 July, entrusting the crown prince Li Zhi to Zhangsun Wuji and Chu Suiliang."]),
      w(649, 108.47, 34.62,
        ['昭陵（今陕西礼泉九嵕山）', '葬于昭陵', '太宗与长孙皇后合葬昭陵，陵墓凿九嵕山主峰为玄宫，开创了唐代帝陵“因山为陵”的制度。陵前刻有他生前所乘六匹战马的浮雕“昭陵六骏”，周围有一百多座功臣贵戚的陪葬墓。'],
        ["Zhaoling (Mount Jiuzong, Liquan, Shaanxi)", "Buried at Zhaoling", "Taizong was buried beside Empress Zhangsun at Zhaoling, a tomb chamber cut into the main peak of Mount Jiuzong that set the Tang pattern of using a mountain as the imperial tomb. Stone reliefs of six of his war horses stood before it, and well over a hundred tombs of ministers and relatives surround it."],
        { wiki: { zh: '唐昭陵', en: 'Zhao Mausoleum (Tang dynasty)' } }),
    ],
    wiki: { zh: '唐太宗', en: 'Emperor Taizong of Tang' },
  },
  {
    id: 'xuanzang', name: { zh: '玄奘', en: 'Xuanzang' }, birth: 602, death: 664,
    title: { zh: '高僧、翻译家', en: 'Buddhist monk, pilgrim and translator' }, region: 'china', lineage: 'china', sprite: 'walker',
    summary: {
      zh: '唐代高僧、翻译家，俗姓陈。为求佛法真义，他于629年（一说627年）私自西行，历经艰险抵达印度，在那烂陀寺求学多年，名震五天竺。645年携佛经六百余部回到长安，主持译经1335卷，并口述《大唐西域记》，是研究中亚与南亚古代史地的珍贵文献。',
      en: "Tang-dynasty Buddhist monk, pilgrim and translator, surnamed Chen. Seeking authoritative texts, he left China without permission in 629 (some say 627), crossed the deserts and mountains of Central Asia to India and studied for years at Nalanda, winning fame across the subcontinent. He returned to Chang'an in 645 with more than six hundred Buddhist texts and directed the translation of 1,335 fascicles. His Great Tang Records on the Western Regions, dictated to a disciple, remains a prime source for the historical geography of Central and South Asia.",
    },
    route: [
      w(602, 112.79, 34.73,
        ['缑氏（今河南偃师）', '生于洛州缑氏', '玄奘俗姓陈，出身于一个世代为官的儒学家庭，父亲陈惠曾任江陵县令，后辞官归乡。他是四兄弟中最小的一个，二哥先在洛阳净土寺出家，法号长捷，玄奘少年时便跟着他学习佛经。'],
        ["Goushi (now Yanshi, Henan)", "Born at Goushi near Luoyang", "Xuanzang, surnamed Chen, came from a family of Confucian officials; his father Chen Hui had been a county magistrate before retiring to his home town. The youngest of four brothers, he followed the second, who had become a monk at Jingtu Monastery in Luoyang, and began studying Buddhist texts as a boy."]),
      w(615, 112.45, 34.62,
        ['洛阳', '十三岁于洛阳净土寺出家', '隋朝在洛阳度僧，玄奘年纪太小本不合格，主持其事的大理卿郑善果问他为何出家，他答“意欲远绍如来，近光遗法”，遂被破格录取。此后他在净土寺听讲《涅槃经》《摄大乘论》。'],
        ["Luoyang", "Ordained as a novice at thirteen", "When the Sui court held an ordination at Luoyang, Xuanzang was under age. Asked by the presiding official Zheng Shanguo why he wished to become a monk, he replied that he wanted to carry on the Buddha's work and make his teaching shine, and he was admitted as an exception. He went on to study the Nirvana Sutra at Jingtu Monastery."]),
      w(622, 104.07, 30.67,
        ['成都', '避乱入蜀，在成都受具足戒', '隋末洛阳战乱，玄奘与兄长先到长安，又南下入蜀，当时许多高僧都聚集在成都。他在这里遍听诸师讲论，622年满二十岁时受具足戒，随后不顾兄长挽留，乘船出三峡，到荆州、相州、赵州等地继续游学。'],
        ["Chengdu", "Takes refuge in Shu and is fully ordained", "As war engulfed Luoyang at the end of the Sui, Xuanzang and his brother went to Chang'an and then south to Chengdu, where many eminent monks had gathered. He studied under them and received full ordination in 622 at the age of twenty, then left by boat through the Three Gorges, against his brother's wishes, to seek teachers elsewhere."]),
      w(629, 108.94, 34.34,
        ['长安（今陕西西安）', '为求取真经，私自西行', '玄奘回到长安后，发现各家对经义解说不一，而汉译佛典又多有残缺，于是决心到印度求取原典。他上表请求出关未获批准，629年秋关中遭霜灾，朝廷准许百姓四出就食，他便混在灾民中离开长安（一说在627年）。'],
        ["Chang'an (now Xi'an, Shaanxi)", "Sets out for the west without permission", "Back in Chang'an, Xuanzang found that teachers disagreed on doctrine and that the Chinese translations were incomplete, and resolved to seek the original texts in India. His petition to leave was refused. When frost ruined the harvest in 629 (some say 627) and people were allowed to disperse in search of food, he slipped out among them."]),
      w(629, 102.64, 37.93,
        ['凉州（今甘肃武威）', '在凉州讲经', '凉州是河西的都会，西域商旅往来不绝。玄奘在这里停留一个多月，应邀开讲经论，听众中的西域商人把他的名声带回了各国。凉州都督奉命禁止百姓出境，逼他返回长安，他在当地僧人帮助下昼伏夜行，继续西进。'],
        ["Liangzhou (now Wuwei, Gansu)", "Lectures at Liangzhou", "Liangzhou was the chief city of the Hexi Corridor, thronged with merchants from the Western Regions. Xuanzang stayed over a month lecturing on the sutras, and traders in the audience carried his name home ahead of him. The governor, under orders to stop anyone leaving the country, told him to go back; helped by local monks, he travelled on by night."]),
      w(629, 95.78, 40.52,
        ['瓜州（今甘肃瓜州）', '过玉门关，孤身穿越莫贺延碛', '在瓜州，追捕他的公文已到，州吏李昌同情他，当面撕毁文书催他快走。玄奘由胡人石槃陀引路夜渡葫芦河，绕过玉门关，此后独自一人偷越五座烽燧，走进八百里莫贺延碛。途中他失手打翻水囊，四夜五天滴水未进，几乎丧命。'],
        ["Guazhou (Gansu)", "Slips past Yumen Pass and crosses the Gobi alone", "At Guazhou a warrant for his arrest arrived, but a sympathetic official tore it up and urged him to hurry. Guided across the Hulu River by night, Xuanzang skirted Yumen Pass, crept past five watchtowers alone and entered the Mohoyan desert. There he spilled his water bag and went four nights and five days without a drop, close to death."],
        { wiki: { zh: '玉门关', en: 'Yumen Pass' } }),
      w(630, 93.51, 42.82,
        ['伊吾（今新疆哈密）', '抵达伊吾', '走出沙漠后，玄奘到达西域东端的绿洲伊吾，住进一座寺院，寺中有三位汉僧，其中一位老僧听说有故乡人来，衣不及带、赤脚出迎，抱着他痛哭。高昌王的使者恰在伊吾，回去报告了消息。'],
        ["Yiwu (now Hami, Xinjiang)", "Reaches the oasis of Yiwu", "Out of the desert, Xuanzang came to Yiwu, the easternmost oasis of the Western Regions, and lodged in a monastery where three Chinese monks lived. One old monk, hearing that a countryman had arrived, ran out barefoot and half-dressed and wept as he embraced him. An envoy of the king of Gaochang was in town and reported the news."]),
      w(630, 89.53, 42.85,
        ['高昌（今新疆吐鲁番）', '高昌王麴文泰厚礼相待，结为兄弟', '高昌王麴文泰笃信佛教，派人把玄奘迎到王城，执意要留他长住。玄奘绝食三天以明心志，麴文泰只得让步，与他结为兄弟，又为他剃度四名沙弥，备下足够往返二十年的盘缠和三十匹马，并写信请沿途各国和西突厥可汗关照。'],
        ["Gaochang (near Turpan, Xinjiang)", "Honoured by King Qu Wentai of Gaochang", "Qu Wentai, the devout king of Gaochang, had Xuanzang escorted to his capital and pressed him to stay for good. Only when Xuanzang refused food for three days did the king relent. The two swore brotherhood, and he sent the pilgrim on with novices, horses, funds for a twenty-year journey and letters to the rulers ahead, including the Western Turkic qaghan."],
        { wiki: { zh: '高昌故城', en: 'Gaochang' } }),
      w(630, 82.96, 41.72,
        ['屈支（龟兹，今新疆库车）', '翻越凌山前在此滞留', '玄奘经阿耆尼（焉耆）到达屈支，这里是塔里木盆地北缘最大的佛教中心，僧徒五千余人，习小乘说一切有部。他与当地高僧木叉毱多辩论经义，因凌山积雪未化、道路不通，在此停留了六十多天。'],
        ["Kucha (Xinjiang)", "Waits at Kucha for the passes to open", "By way of Karashahr Xuanzang reached Kucha, the largest Buddhist centre on the northern rim of the Tarim Basin, with some five thousand monks of the Sarvastivada school. He debated doctrine with the leading local monk Moksagupta and waited more than sixty days for the snow on the passes ahead to clear."]),
      w(630, 78.4, 41.4,
        ['凌山（天山别迭里山口一带）', '翻越凌山，同行者冻死十之三四', '从跋禄迦国（今阿克苏）向西北，玄奘一行翻越天山的凌山。山上终年冰雪，无处生火做饭，只能卧冰而眠，七天后才走出山地，同行者冻饿而死的有十分之三四，牛马损失更多。下山后他们沿大清池（伊塞克湖）西行。'],
        ["Ling Mountain (Bedel Pass area, Tian Shan)", "Crosses the icy Ling Mountain", "North-west of Aksu, Xuanzang's party climbed over the Tian Shan by the pass he calls Ling Mountain. With no dry place to cook or rest, they slept on the ice. It took seven days to get clear, and three or four in every ten of his companions died of cold and hunger. Beyond lay Lake Issyk-Kul."]),
      w(630, 75.3, 42.84,
        ['素叶城（碎叶，今吉尔吉斯斯坦托克马克附近）', '会见西突厥叶护可汗', '在素叶城，玄奘见到正在游猎的西突厥统叶护可汗。可汗身穿绿绫袍，在饰满金花的大帐里设宴款待，又派一名通晓汉语的少年官员，带着致各国的书信护送他南下，直到迦毕试国。'],
        ["Suyab (near Tokmok, Kyrgyzstan)", "Meets the Western Turkic qaghan", "At Suyab Xuanzang found the Western Turkic ruler Tong Yabghu Qaghan out hunting. The qaghan, in a green satin robe, feasted him in a great tent glittering with gold ornament, and then sent a young officer who knew Chinese to escort him south with letters of introduction as far as Kapisa."]),
      w(630, 66.96, 39.65,
        ['飒秣建（康国，今乌兹别克斯坦撒马尔罕）', '为国王说法', '飒秣建是粟特人的都城，居民信奉祆教，城中两座佛寺早已无僧居住，随行的小沙弥进寺礼拜，竟被人持火驱赶。玄奘为国王讲说人天因果，国王转而敬信，请他度人出家。此后他南行穿过铁门关，进入吐火罗故地。'],
        ["Samarkand (Uzbekistan)", "Preaches to the king of Samarkand", "Samarkand was the chief city of the Sogdians, who followed Zoroastrian rites; its two Buddhist monasteries stood empty, and Xuanzang's novices were chased out with burning brands when they tried to worship there. He preached to the king, who was won over and let him ordain monks. From here he went south through the Iron Gate into Tokharistan."]),
      w(630, 66.9, 36.76,
        ['缚喝（今阿富汗巴尔赫）', '礼佛遗迹', '缚喝国佛教兴盛，有寺院百余所、僧徒三千余人，被称为“小王舍城”。玄奘在城外的纳缚僧伽蓝瞻礼佛澡罐、佛牙和佛扫帚，并跟随当地的小乘高僧般若羯罗学习《毗婆沙论》一个多月。'],
        ["Balkh (Afghanistan)", "Venerates relics at Balkh", "Balkh was a flourishing Buddhist city with about a hundred monasteries and three thousand monks, nicknamed 'Little Rajagriha'. At the Nava Vihara outside the walls Xuanzang venerated relics said to be the Buddha's washing basin, tooth and broom, and he spent over a month studying Abhidharma texts with the local scholar Prajnakara."]),
      w(630, 67.83, 34.82,
        ['梵衍那（今阿富汗巴米扬）', '瞻礼巴米扬大佛', '玄奘冒着风雪翻越兴都库什山，来到山谷中的梵衍那国。他在《大唐西域记》里记下王城东北山崖上的两尊立佛，一尊高一百四五十尺，“金色晃曜，宝饰焕烂”，另一尊高百余尺。这两尊大佛在2001年被塔利班炸毁。'],
        ["Bamiyan (Afghanistan)", "Sees the great Buddhas of Bamiyan", "Xuanzang crossed the Hindu Kush through snowstorms to the valley kingdom of Bamiyan. In his Records he described the two standing Buddhas cut in the cliff north-east of the royal city, the larger gleaming with gold and precious ornament. The statues stood until the Taliban blew them up in 2001."],
        { wiki: { zh: '巴米扬大佛', en: 'Buddhas of Bamiyan' } }),
      w(631, 74.8, 34.08,
        ['迦湿弥罗（今克什米尔斯利那加）', '学法两年', '玄奘经迦毕试、健驮逻和呾叉始罗进入印度西北，来到迦湿弥罗。国王亲自出迎，拨给二十名书手替他抄写经论。他跟随一位年近七十的高僧学习《俱舍论》《顺正理论》和因明、声明，在这里住了约两年。'],
        ["Kashmir (Srinagar)", "Studies in Kashmir for two years", "By way of Kapisa, Gandhara and Taxila Xuanzang entered north-west India and came to Kashmir. The king met him in person and assigned twenty scribes to copy texts for him. He stayed about two years studying Abhidharma treatises, logic and Sanskrit grammar under a master who was nearly seventy."]),
      w(633, 84.991, 24.696,
        ['菩提伽耶（今印度比哈尔邦）', '瞻礼菩提树与金刚座', '离开迦湿弥罗后，玄奘沿恒河流域东行，巡礼舍卫城、迦毗罗卫、拘尸那揭罗、鹿野苑等佛陀遗迹，途中曾在恒河上遭强盗劫持，险些被杀来祭神。到了佛陀成道的菩提树下，他五体投地，悲叹自己生在佛法衰微的时代。年份为约数。'],
        ["Bodh Gaya (Bihar, India)", "Worships at the Bodhi tree", "Leaving Kashmir, Xuanzang travelled east down the Ganges plain, visiting Sravasti, Kapilavastu, Kushinagar, Sarnath and other sites of the Buddha's life; on the river he was seized by pirates who meant to sacrifice him. At the Bodhi tree, where the Buddha attained enlightenment, he prostrated himself and wept that he had been born in a lesser age. The date is approximate."],
        { wiki: { zh: '摩诃菩提寺', en: 'Mahabodhi Temple' } }),
      w(633, 85.44, 25.135,
        ['那烂陀寺（今印度比哈尔邦）', '拜戒贤法师为师，研习《瑜伽师地论》', '那烂陀寺是当时印度最大的佛教学府，据说常住僧众上万人。年事已高的住持戒贤法师专门为玄奘开讲《瑜伽师地论》，前后十五个月才讲完一遍。玄奘在寺中学习五年，兼习梵文和婆罗门典籍，成为寺中通晓经论最多的大德之一。'],
        ["Nalanda (Bihar, India)", "Studies the Yogacara texts under Silabhadra", "Nalanda was the greatest Buddhist monastery-university in India, said to house some ten thousand monks. Its aged abbot Silabhadra expounded the Yogacarabhumi-sastra specially for Xuanzang, taking fifteen months to go through it once. Xuanzang studied here for five years, also learning Sanskrit grammar and Brahmanical texts, and ranked among its most learned masters."],
        { wiki: { zh: '那烂陀寺', en: 'Nalanda mahavihara' } }),
      w(639, 79.7, 12.83,
        ['建志补罗（今印度泰米尔纳德邦甘吉布勒姆）', '南游至达罗毗荼国', '玄奘离开那烂陀寺，用几年时间周游东印度和南印度，经耽摩栗底、羯陵伽、案达罗，最南到达罗毗荼国的都城建志补罗。他本想从这里渡海去僧伽罗国（今斯里兰卡），听说岛上国王去世、正闹饥荒，便折向西印度北返。年份为约数。'],
        ["Kanchipuram (Tamil Nadu, India)", "Travels to the far south of India", "Leaving Nalanda, Xuanzang spent several years touring eastern and southern India, by way of Tamralipti, Kalinga and Andhra, as far as Kanchipuram, capital of the Dravida country, about 639. He had meant to sail on to Sri Lanka but, hearing that its king had died and famine had broken out, turned back north through western India."]),
      w(642, 91.74, 26.14,
        ['迦摩缕波（今印度阿萨姆邦古瓦哈提）', '应鸠摩罗王之邀东行', '玄奘回到那烂陀寺后，先后与顺世外道和小乘论师辩论，声名日盛。东印度迦摩缕波国的鸠摩罗王再三遣使相邀，他前往住了一个多月，并听人说起从这里向东两个月可到蜀地西南边境，只是山川险阻、瘴气毒害。'],
        ["Kamarupa (now Guwahati, Assam)", "Visits King Kumara of Kamarupa", "Back at Nalanda, Xuanzang won renown in debates with rival schools. King Kumara (Bhaskaravarman) of Kamarupa in eastern India sent repeated invitations, and he spent over a month at his court. There he heard that the south-western border of Shu lay about two months' journey to the east, across mountains and malarial jungle."]),
      w(642, 79.9, 27.05,
        ['曲女城（今印度北方邦卡瑙季）', '戒日王召开大会，玄奘论辩无人能难', '北印度的霸主戒日王把玄奘从迦摩缕波接到身边，在都城曲女城召集五印度十八国国王和数千名僧人、婆罗门举行法会，由玄奘宣讲大乘教义。据《慈恩传》，论题悬挂十八天，无人能驳倒。随后他又随戒日王到钵罗耶伽参加七十五天的无遮大会。'],
        ["Kannauj (Uttar Pradesh, India)", "Triumphs at Harsha's great assembly", "Harsha, the leading ruler of northern India, brought Xuanzang from Kamarupa and convened at his capital Kannauj an assembly of eighteen kings and thousands of monks and Brahmins, before whom Xuanzang expounded Mahayana doctrine. His biography says his thesis was posted for eighteen days and no one could refute it. He then attended Harsha's seventy-five-day almsgiving at Prayaga."]),
      w(643, 74.5, 37.5,
        ['葱岭（帕米尔高原）', '启程东归，翻越葱岭', '玄奘谢绝戒日王的挽留，带着经卷和佛像，用大象驮运，取道西北印度回国。渡印度河时船只倾覆，损失了五十夹经本和花种，他停下来派人补抄。此后他翻越兴都库什山和葱岭，经朅盘陀（今塔什库尔干）下到塔里木盆地。'],
        ["Pamirs (Congling)", "Starts for home across the Pamirs", "Declining Harsha's pleas to stay, Xuanzang set out through north-west India with his texts and images loaded on an elephant. A boat capsized in the Indus, losing fifty bundles of manuscripts and his flower seeds, and he halted to have copies made. He then crossed the Hindu Kush and the Pamirs and came down by Tashkurgan into the Tarim Basin."]),
      w(644, 79.92, 37.11,
        ['于阗（今新疆和田）', '上表唐太宗请求归国', '玄奘沿塔里木盆地南缘到达于阗，受到国王礼遇，在此为僧众讲经。他一面派人到屈支、疏勒补抄渡河时失落的经本，一面托高昌商人带表文到长安，陈述当年私自出关的经过，七八个月后接到唐太宗欢迎他回国的敕书。'],
        ["Khotan (Hotan, Xinjiang)", "Writes to Emperor Taizong asking to return", "Following the southern rim of the Tarim Basin, Xuanzang reached Khotan, where the king received him with honour and he lectured to the monks. He sent to Kucha and Kashgar for copies of the texts lost in the Indus, and by a merchant caravan sent a memorial to Chang'an explaining his unauthorised departure. Some months later the emperor's reply welcomed him home."]),
      w(645, 108.94, 34.34,
        ['长安', '携佛经六百五十七部归国', '645年正月，玄奘回到阔别十六年的长安，百姓夹道迎观。他带回佛经520夹、657部，以及佛像和舍利。随后他到洛阳谒见正准备东征的唐太宗，谢绝还俗从政的劝说，回长安弘福寺组织译场，并口述《大唐西域记》，由弟子辩机笔录。'],
        ["Chang'an", "Returns with 657 Buddhist texts", "In the first month of 645 Xuanzang re-entered Chang'an after some sixteen years, as crowds lined the streets. He brought 657 texts in 520 bundles, with images and relics. Received by Taizong at Luoyang, he declined to leave the monkhood for office, set up a translation bureau at Hongfu Monastery and dictated the Records of the Western Regions to his disciple Bianji."]),
      w(652, 108.964, 34.219,
        ['长安大慈恩寺', '主持修建大雁塔', '648年太子李治为追念母亲建成大慈恩寺，请玄奘任上座，并设译经院。652年玄奘奏请在寺内建塔，用来安放从印度带回的经像，他亲自参与搬运砖石。这座塔即大雁塔，最初为五层，武则天时改建加高，今为七层。'],
        ["Great Ci'en Monastery, Chang'an", "Builds the Great Wild Goose Pagoda", "In 648 the crown prince Li Zhi completed Ci'en Monastery in memory of his mother and installed Xuanzang as its head, with a translation hall. In 652 Xuanzang asked to build a pagoda there for the scriptures and images from India, and carried bricks himself. First built with five storeys, the Great Wild Goose Pagoda was later rebuilt and now has seven."],
        { wiki: { zh: '大雁塔', en: 'Giant Wild Goose Pagoda' } }),
      w(664, 109.06, 35.25,
        ['玉华宫（今陕西铜川）', '译经途中圆寂', '659年玄奘迁到长安以北山中的玉华寺，这里原是唐太宗的避暑离宫。他用四年时间译完六百卷的《大般若经》，心力交瘁，664年春圆寂。十九年间，他主持译出经论75部、1335卷。'],
        ["Yuhua Palace (now Tongchuan, Shaanxi)", "Dies while still translating", "In 659 Xuanzang moved to Yuhua Monastery in the hills north of Chang'an, a former summer palace of Taizong. There he spent four years translating the six-hundred-fascicle Great Perfection of Wisdom Sutra. Exhausted, he died early in 664. In nineteen years he had directed the translation of 75 works in 1,335 fascicles."]),
    ],
    wiki: { zh: '玄奘', en: 'Xuanzang' },
  },
  {
    id: 'wu-zetian', name: { zh: '武则天', en: 'Wu Zetian' }, birth: 624, death: 705,
    title: { zh: '武周皇帝', en: 'Emperor of the Wu Zhou dynasty' }, region: 'china', lineage: 'china', sprite: 'crown',
    summary: {
      zh: '中国历史上唯一的正统女皇帝，名曌，祖籍并州文水。初为唐太宗才人，后为唐高宗皇后，与高宗并称“二圣”。690年改国号为周，以洛阳为“神都”。她任用酷吏打击异己，也大力发展科举、提拔寒门士人。705年被迫退位，同年去世，以皇后身份与高宗合葬乾陵。',
      en: "The only woman to rule China as emperor in her own right. Of a family from Wenshui in Bingzhou, she entered the palace as a junior consort of Emperor Taizong and later became empress to Emperor Gaozong, sharing power with him as one of the 'Two Sages'. In 690 she proclaimed her own Zhou dynasty with Luoyang as its 'Divine Capital'. She used secret police against opponents but also expanded the examinations and promoted men of modest background. Forced to abdicate in 705, she died that year and was buried with Gaozong at Qianling.",
    },
    route: [
      w(624, 108.94, 34.34,
        ['长安（一说利州）', '生于唐初功臣之家', '武则天的父亲武士彟是并州文水人，早年经营木材致富，因资助李渊起兵而成为唐朝开国功臣，官至工部尚书；母亲杨氏出身隋朝宗室。她的出生地史无明文，有长安、利州（今四川广元）等说法，此处从长安说。'],
        ["Chang'an (or, by another account, Lizhou)", "Born to a founding official of the Tang", "Her father Wu Shiyue, a native of Wenshui in Bingzhou, had grown rich in the timber trade and backed Li Yuan's rising, ending as a minister of the new Tang dynasty; her mother, Lady Yang, came from the Sui imperial clan. No source records her birthplace: Chang'an and Lizhou (Guangyuan, Sichuan) are both proposed, and Chang'an is followed here."]),
      w(628, 105.84, 32.44,
        ['利州（今四川广元）', '随父在利州度过童年', '武士彟出任利州都督，年幼的武则天随父母在嘉陵江畔的利州住了几年，后来又随父亲转任荆州。635年父亲在荆州任上去世，她与母亲受到异母兄长的冷遇。广元的皇泽寺相传是为纪念她而建。年份为约数。'],
        ["Lizhou (now Guangyuan, Sichuan)", "Spends her childhood at Lizhou", "When Wu Shiyue was posted as commander of Lizhou, about 628, the young girl lived for some years in the town on the Jialing River, and later followed him to Jingzhou. He died in office there in 635, leaving her and her mother to the cold treatment of her half-brothers. Huangze Temple in Guangyuan is traditionally linked to her memory."]),
      w(637, 108.94, 34.34,
        ['长安太极宫', '十四岁入宫，为唐太宗才人', '唐太宗听说武士彟的女儿容貌出众，召入宫中封为五品才人，赐号“武媚”。相传临行时母亲杨氏痛哭，她却说：“见天子焉知非福，何儿女悲乎？”她在太宗后宫十二年，地位没有变化。'],
        ["Taiji Palace, Chang'an", "Enters the palace at fourteen as Taizong's consort", "Hearing of her beauty, Emperor Taizong summoned Wu Shiyue's daughter to the palace as a cairen, a consort of the fifth rank. The story goes that when her mother wept at parting she replied, 'Who says that meeting the Son of Heaven is not good fortune?' In twelve years in Taizong's household she rose no higher."]),
      w(649, 108.94, 34.3,
        ['感业寺（长安）', '太宗去世后入感业寺为尼', '649年太宗去世，按惯例没有子女的嫔妃要出家为尼，史书说武氏入了感业寺。即位的高宗李治早在做太子时就与她相识，据《资治通鉴》，他在太宗忌日到寺中行香，两人相见而泣；王皇后为了与萧淑妃争宠，暗中让她蓄发，接回宫中。'],
        ["Ganye Temple (Chang'an)", "Becomes a nun after Taizong's death", "When Taizong died in 649, his childless consorts were by custom sent to a convent, and the histories place Lady Wu at Ganye Temple. The Zizhi Tongjian says that the new emperor Gaozong, who already knew her, wept with her when he came to offer incense on his father's anniversary. Empress Wang, to undercut a rival, had her brought back to the palace."]),
      w(655, 108.94, 34.34,
        ['长安', '被唐高宗立为皇后', '武氏回宫后封为昭仪，很快压倒王皇后和萧淑妃。655年，高宗不顾长孙无忌、褚遂良等元老的反对，在李勣“此陛下家事”一语的支持下废黜王皇后，立武氏为皇后。此后几年，反对她的大臣相继被贬逐或处死。'],
        ["Chang'an", "Made empress by Emperor Gaozong", "Back in the palace as a consort of the second rank, Lady Wu soon eclipsed Empress Wang and Consort Xiao. In 655 Gaozong overrode the elder statesmen Zhangsun Wuji and Chu Suiliang, encouraged by Li Ji's remark that this was 'a family matter', deposed Empress Wang and installed Wu in her place. Within a few years her opponents had been exiled or put to death."]),
      w(664, 108.96, 34.29,
        ['长安大明宫', '垂帘听政，与高宗并称“二圣”', '高宗长期苦于风眩头痛，自660年起常让武后代为处理奏章。664年他与宰相上官仪密谋废后，事泄后上官仪被杀。从此每逢上朝，武后都在御座后垂帘而坐，政事无论大小一同裁决，朝野合称“二圣”。'],
        ["Daming Palace, Chang'an", "Rules beside Gaozong as one of the 'Two Sages'", "Gaozong suffered from dizziness and headaches, and from about 660 he often left memorials to the empress. In 664 he secretly discussed deposing her with the chancellor Shangguan Yi; she found out, and Shangguan Yi was executed. Thereafter she sat behind a screen at every audience and shared every decision, and the pair were known as the Two Sages."],
        { wiki: { zh: '大明宫', en: 'Daming Palace' } }),
      w(666, 117.1, 36.25,
        ['泰山（今山东泰安）', '参与泰山封禅', '666年正月，高宗到泰山举行封禅大典。按旧制，祭地的禅礼由公卿充当亚献，武后以祭祀对象中有先代皇后为由，自请率内外命妇行亚献礼。这是皇后第一次在封禅中担任主要角色，随行的还有突厥、于阗、波斯、新罗、倭国等国使节。'],
        ["Mount Tai (Tai'an, Shandong)", "Takes part in the sacrifices at Mount Tai", "In the first month of 666 Gaozong performed the feng and shan sacrifices at Mount Tai. Arguing that the rite to Earth honoured past empresses, the empress claimed the second offering, traditionally made by ministers, and led the court ladies in performing it. No empress had taken such a part before. Envoys from the Turks, Khotan, Persia, Silla and Japan attended."],
        { wiki: { zh: '泰山', en: 'Mount Tai' } }),
      w(675, 112.47, 34.555,
        ['龙门奉先寺（今河南洛阳）', '资助开凿卢舍那大佛', '洛阳城南龙门山的奉先寺大像龛由高宗下令开凿，据龛旁的造像记，武后于672年“助脂粉钱二万贯”，工程在675年完成。主尊卢舍那佛通高17米多，面容丰满端庄，民间相传是依照武则天的容貌雕成的。'],
        ["Fengxian Temple, Longmen (Luoyang, Henan)", "Helps fund the great Vairocana Buddha", "The colossal shrine of Fengxian Temple in the Longmen cliffs south of Luoyang was commissioned by Gaozong. According to the inscription beside it, the empress gave twenty thousand strings of her 'cosmetics money' in 672, and the work was finished in 675. Popular tradition holds that the serene face of the central Vairocana, over 17 metres high, was modelled on her own."],
        { wiki: { zh: '龙门石窟', en: 'Longmen Grottoes' } }),
      w(684, 112.45, 34.62,
        ['洛阳', '废中宗，临朝称制', '683年底高宗在洛阳去世，太子李显即位，是为中宗。两个月后，武后以他要把天下让给岳父为由将其废为庐陵王，改立幼子李旦（睿宗），自己临朝称制，改东都洛阳为“神都”。同年徐敬业在扬州起兵反对，不到三个月即被平定。'],
        ["Luoyang", "Deposes Zhongzong and rules as regent", "Gaozong died at the end of 683 and his son Li Xian succeeded as Zhongzong. Two months later the empress dowager deposed him for a rash remark about giving the empire to his father-in-law, installed her youngest son Li Dan as a figurehead and governed herself, renaming Luoyang the Divine Capital. Xu Jingye's revolt at Yangzhou was crushed within three months."]),
      w(690, 112.45, 34.62,
        ['洛阳（神都）', '改唐为周，登基称帝', '此前几年，她修建高大的明堂，宣扬《大云经疏》中“女主当国”之说，又有数万人上表劝进。690年重阳节，年过六旬的武则天在洛阳则天门登基，改国号为周，自称“圣神皇帝”。她在位期间亲自策问贡士，破格选用人才，也纵容酷吏罗织罪名。'],
        ["Luoyang (the Divine Capital)", "Proclaims the Zhou dynasty and takes the throne", "Years of preparation came first: a towering Mingtang hall, a Buddhist commentary foretelling a female ruler, and petitions with tens of thousands of names. On the Double Ninth festival of 690 Wu Zetian, in her mid-sixties, ascended the throne at Luoyang as emperor of a new Zhou dynasty. She promoted talent freely, examining candidates in person, yet gave free rein to her secret police."],
        { wiki: { zh: '武周', en: 'Wu Zhou' } }),
      w(696, 113.04, 34.48,
        ['嵩山（今河南登封）', '封禅嵩山', '武则天把嵩山尊为“神岳”，696年亲自登山行封礼，又在少室山行禅礼，改年号为“万岁登封”，嵩阳县和阳城县因此改名登封、告成，沿用至今。700年她再游嵩山，派道士投下一枚祈求除罪的金简，1982年在峻极峰被人发现。'],
        ["Mount Song (Dengfeng, Henan)", "Performs the feng and shan rites at Mount Song", "Wu Zetian honoured Mount Song as the 'Divine Peak' and in 696 climbed it to perform the feng sacrifice, with the shan rite at nearby Shaoshi. She named the new era 'Wansui Dengfeng', and the counties renamed Dengfeng and Gaocheng still bear those names. A gold tablet asking the gods to remit her sins, deposited on the mountain in 700, was found there in 1982."],
        { wiki: { zh: '嵩山', en: 'Mount Song' } }),
      w(701, 108.94, 34.34,
        ['长安', '重返长安，居住两年', '701年冬，武则天离开住了近二十年的洛阳，率朝廷西返长安，改年号为“长安”，在这里住了两年，703年冬又回到神都。这时她已年近八十，朝政多委于宠臣张易之、张昌宗兄弟；此前她已召回庐陵王李显、立为太子，皇位归还李唐之势已定。'],
        ["Chang'an", "Returns to Chang'an for two years", "In the winter of 701 Wu Zetian left Luoyang, her home for nearly twenty years, and took the court back to Chang'an, naming the new era after the city. She stayed two years before returning east in late 703. Now close to eighty, she left much business to her favourites Zhang Yizhi and Zhang Changzong; her son Li Xian had already been recalled as heir."]),
      w(705, 112.45, 34.62,
        ['洛阳上阳宫', '神龙政变后退位，同年病逝', '705年正月武则天病重，宰相张柬之等率禁军入宫杀死张易之兄弟，拥立太子李显复位，恢复唐朝国号。她被迁到洛阳城西的上阳宫，尊为“则天大圣皇帝”，这年冬天去世。遗制去掉帝号，称“则天大圣皇后”。'],
        ["Shangyang Palace, Luoyang", "Abdicates after a palace coup and dies", "Early in 705, as Wu Zetian lay ill, the chancellor Zhang Jianzhi and his allies led guards into the palace, killed the Zhang brothers and restored Li Xian and the Tang. She was moved to Shangyang Palace on the west side of Luoyang with the title 'Zetian, Great Sage Emperor' and died that winter. Her will gave up the imperial title for that of empress."]),
      w(706, 108.22, 34.57,
        ['乾陵（今陕西乾县梁山）', '与高宗合葬乾陵', '706年，武则天的灵柩由洛阳运回关中，与高宗合葬于梁山乾陵，这是中国唯一一座葬有两位皇帝的陵墓。陵前西侧是她为高宗所立的述圣纪碑，东侧为她而立的石碑却没有刻碑文，后人称为“无字碑”。'],
        ["Qianling (Mount Liang, Qian County, Shaanxi)", "Buried with Gaozong at Qianling", "In 706 Wu Zetian's coffin was brought back from Luoyang and laid beside Gaozong in the Qianling tomb on Mount Liang, the only Chinese mausoleum to hold two reigning emperors. On one side of the approach stands the stele she raised to Gaozong's memory; the tall stele set up for her on the other side was left without an inscription."],
        { wiki: { zh: '乾陵', en: 'Qianling Mausoleum' } }),
    ],
    wiki: { zh: '武则天', en: 'Wu Zetian' },
  },
  {
    id: 'jianzhen', name: { zh: '鉴真', en: 'Jianzhen' }, birth: 688, death: 763,
    title: { zh: '律宗高僧', en: 'Buddhist monk of the Vinaya school' }, region: 'china', lineage: 'china', sprite: 'ship',
    summary: {
      zh: '唐代高僧、律宗大师，扬州人。他应日本僧人邀请，自742年起先后六次东渡，历经海难、官府阻拦和失明等挫折，终于在753年抵达日本。他在奈良东大寺设坛授戒，创建唐招提寺，传入律宗与建筑、医药、雕塑等唐朝文化，被日本尊为“过海大师”。',
      en: "Tang-dynasty Buddhist monk and master of the Vinaya (monastic discipline) school, a native of Yangzhou. Invited by Japanese monks, he made six attempts from 742 to cross to Japan, enduring shipwreck, official obstruction and the loss of his sight, and finally arrived in 753. He set up an ordination platform at Tōdai-ji in Nara and founded Tōshōdai-ji, bringing with him the Vinaya tradition along with Tang architecture, medicine and sculpture. In Japan he is revered under the name Ganjin.",
    },
    route: [
      w(688, 119.42, 32.39,
        ['扬州（今江苏扬州）', '生于扬州江阳县', '鉴真俗姓淳于，生于长江与大运河交汇处的商业都会扬州，父亲是在家居士，曾随扬州大云寺的智满禅师受戒。十四岁那年，他随父亲到大云寺礼佛，深受感动，请求出家，就在这座寺院做了沙弥。'],
        ["Yangzhou (Jiangsu)", "Born at Jiangyang in Yangzhou", "Jianzhen, whose family name was Chunyu, was born in Yangzhou, the great trading city where the Grand Canal meets the Yangtze. His father was a lay Buddhist who had taken precepts from the monk Zhiman of Dayun Temple. At fourteen, moved by a visit to the temple with his father, the boy asked to enter it as a novice."]),
      w(708, 108.94, 34.34,
        ['长安（今陕西西安）', '于长安实际寺受具足戒，研习律宗', '鉴真先在扬州从道岸律师受菩萨戒，随后北上洛阳、长安游学。708年他在长安实际寺由弘景律师主持受具足戒，此后几年往来两京，研习《四分律》和天台教义，也留心建筑、医药等寺院技艺。'],
        ["Chang'an (now Xi'an, Shaanxi)", "Receives full ordination at Shiji Temple", "After taking the bodhisattva precepts from the Vinaya master Dao'an in Yangzhou, Jianzhen went north to study in Luoyang and Chang'an. In 708 he was fully ordained at Shiji Temple in Chang'an under the master Hongjing. For several years he studied the Four-Part Vinaya in the two capitals, along with Tiantai doctrine and practical arts such as building and medicine."]),
      w(713, 119.42, 32.39,
        ['扬州大明寺', '回扬州弘法，成为一方宗师', '鉴真回到扬州，在大明寺等处讲律授戒。此后三十年间，他主持修建寺院、塑造佛像，设悲田院救济贫病，据传记记载，前后经他授戒的僧俗多达四万余人，被誉为江淮一带的授戒大师。年份为约数。'],
        ["Daming Temple, Yangzhou", "Returns to teach in Yangzhou", "Back in Yangzhou from about 713, Jianzhen lectured on the Vinaya and conferred ordinations at Daming Temple and elsewhere. Over the next thirty years he built monasteries, commissioned images and ran charitable infirmaries; his biography claims that more than forty thousand people received the precepts from him, and he was regarded as the leading ordination master of the lower Yangtze."],
        { wiki: { zh: '大明寺', en: 'Daming Temple' } }),
      w(742, 119.42, 32.39,
        ['扬州大明寺', '应日本僧人荣叡、普照之请发愿东渡', '日本佛教当时缺少合格的授戒师，留学僧荣叡、普照奉命到唐朝聘请高僧，在中国寻访了十年。742年他们来到大明寺恳请，鉴真问弟子谁愿前往，众人默然，他说：“是为法事也，何惜身命！诸人不去，我即去耳。”'],
        ["Daming Temple, Yangzhou", "Vows to go to Japan", "Japan lacked masters qualified to ordain monks properly, and the student monks Yōei and Fushō had spent ten years in China seeking one. In 742 they came to Daming Temple. When Jianzhen asked which of his disciples would go, none spoke, and he said: 'This is for the Dharma; why grudge our lives? If none of you will go, I will.'"]),
      w(744, 121.74, 29.85,
        ['明州阿育王寺（今浙江宁波）', '前三次东渡失败，栖身阿育王寺', '第一次东渡因同行僧人诬告他们勾结海盗而夭折。743年底再次出发，船在长江口外的狼沟浦被风浪击破；修好后第三次出海，又在舟山一带触礁，众人困在荒岛上，获救后被官府安置在明州阿育王寺。'],
        ["Ayuwang Temple, Mingzhou (now Ningbo, Zhejiang)", "Three failed attempts end at Ayuwang Temple", "The first attempt collapsed when a monk falsely accused the party of plotting with pirates. Setting out again at the end of 743, the ship was battered by waves off the Yangtze mouth; repaired, it sailed a third time and was wrecked among the Zhoushan islands. The survivors, stranded on a barren island, were rescued and lodged by the authorities at Ayuwang Temple."],
        { sea: true, via: [[121.0, 31.8], [122.2, 31.2], [122.0, 30.4]] }),
      w(744, 121.26, 28.65,
        ['黄岩禅林寺（今浙江台州）', '第四次东渡在黄岩受阻', '鉴真决定改从福州出海，以巡礼圣迹为名带弟子南下，途中登天台山参拜国清寺。弟子灵祐等人不忍师父冒险，向官府告发，一行人在黄岩禅林寺被追上，鉴真被差役一路护送回扬州，受到严密看管。'],
        ["Chanlin Temple, Huangyan (now Taizhou, Zhejiang)", "Fourth attempt stopped at Huangyan", "Jianzhen now planned to sail from Fuzhou and led his party south on the pretext of a pilgrimage, visiting Guoqing Temple on Mount Tiantai on the way. His disciple Lingyou, fearing for his master's life, informed the authorities. Officers caught up with them at Chanlin Temple in Huangyan and escorted Jianzhen back to Yangzhou under guard."]),
      w(748, 119.42, 32.39,
        ['扬州崇福寺', '第五次东渡，自扬州出发', '荣叡、普照避了几年风头后再到扬州，鉴真重新备办船只粮食。748年夏，一行三十多人从扬州崇福寺出发，沿运河入长江东下，在长江口和舟山群岛一带等候顺风，停留了几个月，入冬后才驶向大洋。'],
        ["Chongfu Temple, Yangzhou", "Sets out on the fifth attempt", "After lying low for some years, Yōei and Fushō came back to Yangzhou and Jianzhen again fitted out a ship. In summer 748 a party of over thirty left Chongfu Temple, went down the canal and the Yangtze and waited for months near the river mouth and the Zhoushan islands for a fair wind, putting out to the open sea only in early winter."]),
      w(748, 109.5, 18.25,
        ['振州（今海南三亚）', '海上遇风暴，漂至海南岛', '船出海后遇上猛烈的东北风，在怒涛中向南漂流了十四天，淡水用尽，众人只能嚼生米、饮海水。船最后漂到海南岛南端的振州，当地官员把他们安置在大云寺，鉴真在这里住了一年，主持重修了寺中的佛殿。'],
        ["Zhenzhou (now Sanya, Hainan)", "Driven by a storm to Hainan Island", "Once at sea the ship was caught by a violent north-east wind and drifted south for fourteen days through huge waves; the fresh water ran out and the company chewed raw rice and drank seawater. They came ashore at Zhenzhou on the southern tip of Hainan, where officials housed them in the Dayun Temple. Jianzhen stayed a year and rebuilt its Buddha hall."],
        { sea: true, via: [[122.3, 30.5], [121.0, 26.0], [117.5, 22.5], [112.0, 18.8]] }),
      w(749, 110.29, 25.27,
        ['桂州始安（今广西桂林）', '北返途中留居桂林', '鉴真一行由振州经万安州到崖州，渡过琼州海峡在雷州登岸，再经今广西境内北上。始安都督冯古璞步行出城迎接，请他在开元寺住了一年，为官员和僧俗授菩萨戒。随后他应广州太守卢奂之邀，顺桂江、西江东下。'],
        ["Shi'an in Guizhou (now Guilin, Guangxi)", "Stays a year at Guilin on the way north", "From Zhenzhou the party went round Hainan to Yazhou, crossed the strait to the Leizhou peninsula and travelled north through what is now Guangxi. At Shi'an the governor Feng Gupu came out on foot to welcome Jianzhen and kept him a year at Kaiyuan Temple, conferring bodhisattva precepts. He then went downriver towards Guangzhou at the invitation of its prefect."],
        { via: [[110.35, 20.0], [110.1, 20.9]] }),
      w(750, 112.47, 23.05,
        ['端州（今广东肇庆）', '荣叡病逝于端州龙兴寺', '船到端州，追随鉴真奔波了八年的日本僧人荣叡在龙兴寺病逝，鉴真“哀恸悲切”，亲自送葬。端州太守随后把一行人送到广州，当地官员和僧俗出城迎接，鉴真在广州住了一个春天，登坛为人授戒。'],
        ["Duanzhou (now Zhaoqing, Guangdong)", "Yōei dies at Longxing Temple in Duanzhou", "At Duanzhou the Japanese monk Yōei, who had shared eight years of Jianzhen's wanderings, fell ill and died at Longxing Temple; Jianzhen mourned him bitterly and saw him buried. The prefect then escorted the party to Guangzhou, where Jianzhen was welcomed with honour and stayed for a season conferring ordinations."]),
      w(750, 113.6, 24.81,
        ['韶州（今广东韶关）', '在韶州双目失明', '鉴真从广州溯北江到韶州，参拜禅宗六祖慧能住过的寺院。普照在这里辞别北上，鉴真握着他的手流泪说，发愿过海传戒却未能到日本，本愿未遂。据传记记载，他因连年奔波、屡受暑热，眼疾加重，请胡人医治无效，就此失明。此后他翻越大庾岭，于751年回到扬州。'],
        ["Shaozhou (now Shaoguan, Guangdong)", "Loses his sight at Shaozhou", "From Guangzhou Jianzhen went up the North River to Shaozhou and visited the monastery of the Chan patriarch Huineng. Here Fushō took his leave to go north, and Jianzhen wept that his vow to reach Japan was still unfulfilled. His biography says that, worn by travel and the southern heat, his eyes failed; a foreign physician could not help and he went blind. He returned to Yangzhou in 751."]),
      w(753, 119.42, 32.39,
        ['扬州延光寺', '第六次东渡，随日本遣唐使船出发', '753年，回国途中的日本遣唐大使藤原清河、副使大伴古麻吕和在唐多年的阿倍仲麻吕等来到扬州延光寺拜见鉴真，请他同船东渡。因为没有得到朝廷许可，鉴真率弟子二十多人悄悄乘船离开扬州，前往使团停船的港口。'],
        ["Yanguang Temple, Yangzhou", "Leaves with the Japanese embassy on his sixth attempt", "In 753 the returning Japanese ambassador Fujiwara no Kiyokawa, his deputy Ōtomo no Komaro and Abe no Nakamaro, long resident in China, called on Jianzhen at Yanguang Temple and invited him to sail with them. Because the court had not approved his going, he and some two dozen disciples slipped out of Yangzhou in secret by boat."],
        { wiki: { zh: '遣唐使', en: 'Japanese missions to Tang China' } }),
      w(753, 120.62, 31.93,
        ['黄泗浦（今江苏张家港）', '在黄泗浦登上遣唐使船', '鉴真一行顺江而下，到长江南岸的港口黄泗浦与遣唐使船队会合。大使听说官府可能搜查，一度让众人下船，副使大伴古麻吕却暗中把鉴真等人接上自己乘坐的第二船。十一月十六日，四艘船一同启航。'],
        ["Huangsipu (now Zhangjiagang, Jiangsu)", "Boards the embassy ship at Huangsipu", "Jianzhen's party went down the Yangtze to Huangsipu, a port on the south bank, to join the embassy's four ships. Fearing a search, the ambassador had the monks put ashore again, but the deputy envoy Ōtomo no Komaro quietly took Jianzhen and his followers aboard his own vessel, the second ship. The fleet sailed on the sixteenth day of the eleventh month."]),
      w(753, 130.22, 31.27,
        ['秋妻屋浦（今日本鹿儿岛县坊津）', '经阿儿奈波岛，终于登陆日本', '船队先到阿儿奈波岛（今冲绳），再北上时被风吹散。大使和阿倍仲麻吕所乘的第一船漂到安南，鉴真乘坐的第二船经益救岛（今屋久岛），于十二月二十日抵达萨摩国秋妻屋浦。自初次发愿算起，已过去了十一年多。'],
        ["Akimeyaura (now Bōnotsu, Kagoshima, Japan)", "Lands in Japan at last, by way of Okinawa", "The fleet reached Okinawa and was then scattered as it turned north. The first ship, with the ambassador and Abe no Nakamaro, was blown to Annam; the second, carrying Jianzhen, passed Yakushima and on the twentieth day of the twelfth month made land at Akimeyaura in Satsuma. More than eleven years had passed since his vow."],
        { sea: true, via: [[122.0, 31.2], [125.5, 28.2], [127.7, 26.3], [130.5, 30.4]] }),
      w(754, 135.84, 34.69,
        ['奈良东大寺（平城京）', '在东大寺设坛授戒', '鉴真经大宰府、难波于754年二月进入平城京，住进东大寺，朝廷下诏把授戒传律之事全部托付给他。四月，他在大佛殿前筑起戒坛，先为圣武太上天皇、光明皇太后和孝谦天皇授菩萨戒，又为四百多名僧人授戒。这是日本正规授戒制度的开端。'],
        ["Tōdai-ji, Nara (Heijō-kyō)", "Sets up an ordination platform at Tōdai-ji", "By way of Dazaifu and Naniwa, Jianzhen entered the capital Heijō-kyō early in 754 and was lodged at Tōdai-ji, with an edict entrusting ordinations to him. In the fourth month he raised a platform before the Great Buddha Hall and gave the bodhisattva precepts to the retired emperor Shōmu, Empress Dowager Kōmyō and the reigning empress Kōken, then ordained over four hundred monks."],
        { sea: true, via: [[130.6, 32.5], [132.0, 33.5], [135.2, 34.5]], wiki: { zh: '东大寺', en: 'Tōdai-ji' } }),
      w(759, 135.785, 34.675,
        ['唐招提寺（奈良）', '创建唐招提寺', '鉴真辞去僧纲之职后，朝廷把平城京右京已故新田部亲王的旧宅赐给他。759年他在这里创立戒院，名为“唐招提寺”，讲授戒律，四方僧人前来学习。寺中金堂由弟子在他身后建成，是日本现存最重要的奈良时代建筑之一。'],
        ["Tōshōdai-ji (Nara)", "Founds Tōshōdai-ji", "When Jianzhen retired from his office in the monastic administration, the court granted him the former residence of Prince Niitabe in the western part of the capital. There in 759 he founded a monastery for teaching the Vinaya, named Tōshōdai-ji. Its Golden Hall, completed by his disciples after his death, is among the finest surviving buildings of the Nara period."],
        { wiki: { zh: '唐招提寺', en: 'Tōshōdai-ji' } }),
      w(763, 135.785, 34.675,
        ['唐招提寺（奈良）', '圆寂于唐招提寺', '763年春，弟子忍基梦见讲堂的栋梁折断，知道师父将不久于世，便率众为他造像。这年五月六日，鉴真面向西方端坐而逝。那尊干漆夹纻坐像至今保存在唐招提寺，是日本现存最早的肖像雕塑之一，被定为国宝。'],
        ["Tōshōdai-ji (Nara)", "Dies at Tōshōdai-ji", "In spring 763 his disciple Ninki dreamed that the main beam of the lecture hall had broken and, taking it as an omen, had a portrait statue made. On the sixth day of the fifth month Jianzhen died seated facing west. The dry-lacquer statue, still kept at Tōshōdai-ji, is one of the oldest portrait sculptures in Japan and a National Treasure."]),
    ],
    wiki: { zh: '鉴真', en: 'Jianzhen' },
  },
  {
    id: 'li-bai', name: { zh: '李白', en: 'Li Bai' }, birth: 701, death: 762,
    title: { zh: '诗人', en: 'Poet' }, region: 'china', lineage: 'china', sprite: 'walker',
    summary: {
      zh: '唐代伟大的浪漫主义诗人，字太白，号青莲居士，被后人誉为“诗仙”。他二十多岁出蜀，一生漫游大江南北，曾供奉翰林，不久被“赐金放还”；安史之乱中因入永王幕府获罪，流放夜郎，中途遇赦。其诗豪放飘逸、想象瑰丽，代表作有《将进酒》《蜀道难》《静夜思》等，与杜甫并称“李杜”。',
      en: "The great romantic poet of the Tang dynasty, courtesy name Taibai, remembered as the 'Immortal of Poetry'. Leaving Sichuan in his twenties, he spent his life wandering across China. He served briefly at court as a Hanlin academician before being dismissed with a gift of gold; during the An Lushan Rebellion he joined the staff of the Prince of Yong, was condemned to exile in Yelang and pardoned on the way. His verse is bold, free and vividly imaginative, as in 'Bring in the Wine', 'The Road to Shu Is Hard' and 'Quiet Night Thought'. He is paired with Du Fu as 'Li-Du'.",
    },
    route: [
      w(701, 75.3, 42.84,
        ['碎叶城（今吉尔吉斯斯坦托克马克附近）', '相传生于西域碎叶（一说蜀中）', '李白的家世和出生地历来说法不一。据李阳冰《草堂集序》和范传正所撰墓碑，其先祖隋末流落西域，李白生于中亚的碎叶；也有学者认为他生于蜀中。碎叶当时是唐朝安西四镇之一，遗址在今托克马克附近的阿克贝希姆。'],
        ["Suyab (near Tokmok, Kyrgyzstan)", "Born at Suyab, by the traditional account", "Li Bai's ancestry and birthplace are uncertain. The preface by Li Yangbing and the epitaph by Fan Chuanzheng say that his forebears were stranded in the Western Regions at the end of the Sui and that he was born at Suyab in Central Asia; some scholars think he was born in Sichuan. Suyab, then a Tang garrison town, is the site of Ak-Beshim near Tokmok."],
        { wiki: { zh: '碎叶城', en: 'Suyab' } }),
      w(705, 104.75, 31.78,
        ['绵州昌隆（今四川江油）', '随父迁居蜀中青莲乡', '神龙初年，五岁左右的李白随父亲李客从西域迁回内地，定居在绵州昌隆县的青莲乡。他在这里读书、学剑，自称“五岁诵六甲，十岁观百家”，少年时还在附近的大匡山隐居读书，并跟随梓州的隐士赵蕤学习纵横之术。'],
        ["Changlong in Mianzhou (now Jiangyou, Sichuan)", "Settles with his family in Sichuan", "About 705 the five-year-old Li Bai came with his father Li Ke from the Western Regions and settled at Qinglian village in Changlong county. Here he studied and practised swordsmanship; he later claimed to have read widely by the age of ten. As a youth he studied in retreat on nearby Mount Dakuang and learned statecraft from the recluse Zhao Rui."]),
      w(724, 103.33, 29.52,
        ['峨眉山（今四川峨眉山市）', '游成都、峨眉，辞亲出蜀', '二十岁前后，李白游历成都，谒见益州长史苏颋，又登峨眉山。724年秋他乘船沿平羌江（今青衣江）东下离开故乡，途中写下《峨眉山月歌》：“峨眉山月半轮秋，影入平羌江水流。”此后他再没有回过蜀地。'],
        ["Mount Emei (Sichuan)", "Tours Chengdu and Mount Emei, then leaves Shu", "Around the age of twenty Li Bai visited Chengdu, where he called on the senior official Su Ting, and climbed Mount Emei. In autumn 724 he set off downriver from his homeland, writing on the way 'Song of the Moon over Mount Emei', with its half-moon reflected in the Pingqiang River. He never returned to Sichuan."],
        { wiki: { zh: '峨眉山', en: 'Mount Emei' } }),
      w(725, 112.2, 30.35,
        ['江陵（今湖北荆州）', '“仗剑去国，辞亲远游”，出蜀东下', '李白穿过三峡，在荆门写下“山随平野尽，江入大荒流”。到江陵后，他遇见年近八十的著名道士司马承祯，司马承祯称赞他“有仙风道骨，可与神游八极之表”，他为此作《大鹏遇希有鸟赋》。随后他南游洞庭，再顺江东下。'],
        ["Jiangling (now Jingzhou, Hubei)", "Sails out of the gorges, sword at his side", "Passing through the Three Gorges, Li Bai wrote at Jingmen of mountains giving way to the plain and the river flowing into the wilderness. At Jiangling he met the aged Daoist master Sima Chengzhen, who praised his 'air of an immortal', and he answered with a rhapsody on the great Peng bird. He then toured Lake Dongting and went on down the Yangtze."]),
      w(726, 119.42, 32.39,
        ['扬州（广陵）', '东游金陵、扬州，散金三十万', '李白先到金陵，又到当时最繁华的商业都会扬州。他后来在《上安州裴长史书》中自述，在扬州不到一年就“散金三十余万”，都用来接济落魄的公子。这年秋天他卧病旅舍，写下思乡之作，随后又南游苏州、越中。'],
        ["Yangzhou (Guangling)", "Travels to Jinling and Yangzhou, spending freely", "Li Bai went first to Jinling and then to Yangzhou, the richest trading city of the day. In a later letter he boasted that in less than a year there he gave away more than 300,000 cash to gentlemen fallen on hard times. That autumn he lay ill at an inn and wrote of homesickness, before travelling on to Suzhou and Yue."]),
      w(727, 113.68, 31.26,
        ['安陆（今湖北安陆）', '与故相许圉师孙女成婚，“酒隐安陆”', '李白回到江汉一带，在安陆入赘高宗朝宰相许圉师家，娶其孙女为妻，生下女儿平阳和儿子伯禽。他以安陆为家前后约十年，自称“酒隐安陆，蹉跎十年”，其间多次出游，并向地方长官上书求荐，都没有结果。'],
        ["Anlu (Hubei)", "Marries into the Xu family and settles at Anlu", "Back in the middle Yangtze region, Li Bai married a granddaughter of Xu Yushi, a chancellor under Emperor Gaozong, and lived with her family at Anlu; they had a daughter and a son. Anlu was his home for about ten years, 'hidden in wine', as he put it, while he made journeys in search of patrons and wrote to local officials without success."]),
      w(728, 114.3, 30.55,
        ['江夏黄鹤楼（今湖北武汉）', '黄鹤楼送孟浩然', '李白敬重年长十二岁的襄阳诗人孟浩然，曾写道“吾爱孟夫子，风流天下闻”。一年春天，孟浩然要东下扬州，李白在江夏黄鹤楼为他送行，留下名句“孤帆远影碧空尽，唯见长江天际流”。此诗的写作年份有728年、730年等说法。'],
        ["Yellow Crane Tower, Jiangxia (now Wuhan, Hubei)", "Sees off Meng Haoran at Yellow Crane Tower", "Li Bai admired the Xiangyang poet Meng Haoran, twelve years his senior. One spring, when Meng was leaving for Yangzhou, Li Bai saw him off at Yellow Crane Tower and wrote the famous lines about a lone sail vanishing into the blue and the Yangtze flowing to the edge of the sky. The poem is dated variously to 728 or 730."],
        { wiki: { zh: '黄鹤楼', en: 'Yellow Crane Tower' } }),
      w(730, 108.94, 34.34,
        ['长安（今陕西西安）', '初入长安，求仕无成', '多数学者认为，李白在730年前后第一次到长安，住在终南山，想通过玉真公主等人得到引荐，却始终没有机会。“大道如青天，我独不得出”，他失意离开，转游邠州、坊州，又东去梁宋。有人认为《蜀道难》《行路难》就作于这一时期。'],
        ["Chang'an (now Xi'an, Shaanxi)", "A first, fruitless visit to Chang'an", "Most scholars believe Li Bai first came to Chang'an about 730. He lodged in the Zhongnan Mountains and sought introductions through Princess Yuzhen and others, but no opening came. 'The great road is wide as the blue sky, yet I alone cannot get out,' he wrote, and left disappointed. Some date 'The Road to Shu Is Hard' to these years."]),
      w(740, 116.59, 35.41,
        ['东鲁任城（今山东济宁）', '移家东鲁', '许氏夫人去世前后，李白带着儿女迁到东鲁，寓居任城、兖州一带，在这里置了田产。他与孔巢父等五人在徂徕山下的竹溪结社饮酒，号称“竹溪六逸”。此后二十年间，他的家一直在东鲁。年份为约数。'],
        ["Rencheng in Eastern Lu (now Jining, Shandong)", "Moves his family to Shandong", "Around 740, about the time his wife died, Li Bai moved with his children to Eastern Lu and lived around Rencheng and Yanzhou, where he acquired some land. With Kong Chaofu and four others he formed a drinking fellowship at Zhuxi below Mount Culai, the 'Six Idlers of the Bamboo Stream'. His family home remained here for the next twenty years."]),
      w(742, 108.94, 34.34,
        ['长安', '奉诏入京，供奉翰林', '742年秋，唐玄宗下诏征召李白，举荐者有道士吴筠、玉真公主等不同说法。他写下“仰天大笑出门去，我辈岂是蓬蒿人”赶赴长安，贺知章读了他的诗，叹为“谪仙人”。玄宗命他供奉翰林，起草文书、写作应制诗文，《清平调》三首即作于此时。'],
        ["Chang'an", "Summoned to court as a Hanlin academician", "In autumn 742 Emperor Xuanzong summoned Li Bai to court; accounts differ on who recommended him. 'Laughing aloud at the sky I go out the gate; how could a man like me stay among the weeds?' he wrote. He Zhizhang called him a 'banished immortal'. Attached to the Hanlin Academy, he drafted documents and court verse such as the 'Qingping Tunes'."]),
      w(744, 112.45, 34.62,
        ['洛阳', '赐金放还，与杜甫相识', '李白在宫中只是文学侍从，又遭人谗毁，744年春上书请求还山，玄宗“赐金放还”。这年夏天他在洛阳遇见小他十一岁的杜甫，两位诗人一见如故；秋天又与高适同游梁宋，登吹台、访古迹，饮酒赋诗。'],
        ["Luoyang", "Dismissed with gold; meets Du Fu", "At court Li Bai was only a literary attendant, and he had enemies. In spring 744 he asked leave to go, and the emperor sent him away with a gift of gold. That summer in Luoyang he met Du Fu, eleven years younger, and they became friends at once. In autumn they travelled with Gao Shi through the old lands of Liang and Song."]),
      w(745, 116.83, 35.55,
        ['兖州石门（今山东兖州）', '与杜甫同游齐鲁后分别', '李白在齐州紫极宫受道箓，正式成为道士；745年秋天，他与杜甫在东鲁重逢，“醉眠秋共被，携手日同行”。两人在兖州城东的石门分别，李白赠诗说“飞蓬各自远，且尽手中杯”。此后他们再没有见面，杜甫却一生不断写诗怀念他。'],
        ["Shimen, Yanzhou (Shandong)", "Parts from Du Fu after their travels in Shandong", "Newly initiated as a Daoist at Qizhou, Li Bai met Du Fu again in autumn 745 in Eastern Lu, where, Du Fu wrote, they shared a quilt when drunk and walked hand in hand by day. They parted at Shimen, east of Yanzhou, over a last cup of wine. They never met again, though Du Fu went on writing poems about him."]),
      w(747, 118.78, 32.05,
        ['金陵（今江苏南京）', '南游吴越，重到金陵', '李白离开东鲁南下，临行作《梦游天姥吟留别》，结尾写道“安能摧眉折腰事权贵，使我不得开心颜”。他游历越中，又在金陵住了较长时间，《登金陵凤凰台》中“总为浮云能蔽日，长安不见使人愁”，流露出对朝政的忧虑。年份为约数。'],
        ["Jinling (now Nanjing, Jiangsu)", "Travels south to Wu and Yue and returns to Jinling", "Leaving Eastern Lu for the south, Li Bai wrote 'Tianmu Mountain Ascended in a Dream', ending with a refusal to bow and scrape before the powerful. He toured Yue and spent long periods in Jinling about 747. His poem on the Phoenix Terrace there, with floating clouds that hide the sun and Chang'an out of sight, hints at unease over affairs at court."]),
      w(752, 116.4, 39.9,
        ['幽州（今北京）', '北上幽州，目睹安禄山势力', '751年冬李白北上，次年到达安禄山坐镇的幽州。他原想在边塞寻找机会，却看到安禄山厉兵秣马，后来回忆说“十月到幽州，戈鋋若罗星”，并曾登上黄金台痛哭。他很快南返，三年后安史之乱爆发。'],
        ["Youzhou (now Beijing)", "Goes north to Youzhou and sees An Lushan's armies", "Li Bai set out north in the winter of 751 and the next year reached Youzhou, An Lushan's headquarters. He had hoped for an opening on the frontier, but what he saw was an army massing; he later recalled spears and halberds thick as stars and said he wept on the Golden Terrace. He soon turned south again. Three years later An Lushan rebelled."]),
      w(753, 118.76, 30.94,
        ['宣城（今安徽宣城）', '漫游江南，作《独坐敬亭山》', '李白从北方南下到宣城，此后几年常往来于宣城、秋浦、南陵一带。他仰慕曾任宣城太守的南朝诗人谢朓，登谢朓楼作“抽刀断水水更流，举杯消愁愁更愁”，又在城北敬亭山写下“相看两不厌，只有敬亭山”。'],
        ["Xuancheng (Anhui)", "Wanders south of the Yangtze; 'Sitting Alone at Jingting Mountain'", "Back in the south, Li Bai moved for some years between Xuancheng, Qiupu and Nanling. He revered the poet Xie Tiao, once governor here, and at Xie Tiao's tower wrote of drawing a sword to cut water that only flows the faster. On Jingting Mountain he wrote the quatrain in which only he and the mountain never tire of each other."]),
      w(755, 118.13, 30.52,
        ['泾县桃花潭（今安徽泾县）', '游桃花潭，作《赠汪伦》', '李白应邀到泾县游桃花潭，当地人汪伦常用美酒款待他。临别时汪伦带着村人踏歌相送，李白作《赠汪伦》：“桃花潭水深千尺，不及汪伦送我情。”这年冬天，安禄山在范阳起兵。此诗的写作年份为约数。'],
        ["Peach Blossom Pool, Jing County (Anhui)", "Visits Peach Blossom Pool; 'To Wang Lun'", "Li Bai was invited to Peach Blossom Pool in Jing County, where a local man, Wang Lun, kept him supplied with good wine. When he left, Wang Lun and the villagers saw him off with singing and stamping feet, and he wrote that the pool, though a thousand feet deep, was not so deep as Wang Lun's friendship. The date, about 755, is approximate."]),
      w(756, 115.98, 29.56,
        ['庐山（今江西九江）', '安史之乱中隐居庐山，后入永王幕府', '安史之乱爆发后，李白与宗氏夫人南奔，隐居在庐山屏风叠。756年底，玄宗之子永王李璘率水军东下，三次派人上山征聘，李白以为可以借此平乱报国，下山入幕，写下《永王东巡歌》。早年游庐山时，他还留下了《望庐山瀑布》。'],
        ["Mount Lu (Jiujiang, Jiangxi)", "Shelters on Mount Lu, then joins the Prince of Yong", "When the rebellion broke out Li Bai fled south with his wife, Lady Zong, and withdrew to Mount Lu. Late in 756 the Prince of Yong, a son of Xuanzong, came down the Yangtze with a fleet and three times sent for him. Believing he could help put down the rebels, Li Bai joined his staff and wrote songs for the expedition."],
        { wiki: { zh: '庐山', en: 'Mount Lu' } }),
      w(757, 116.0, 29.71,
        ['浔阳（今江西九江）', '永王兵败，李白下浔阳狱', '新即位的肃宗把永王东下视为叛乱，757年初永王兵败被杀。李白从军中逃走，在彭泽被捕，关进浔阳监狱，妻子宗氏四处奔走营救，御史中丞宋若思等人为他开脱，一度将他释放。年底他仍被判长流夜郎（今贵州桐梓一带）。'],
        ["Xunyang (now Jiujiang, Jiangxi)", "Imprisoned at Xunyang after the prince's defeat", "The new emperor Suzong treated his brother's expedition as rebellion, and early in 757 the Prince of Yong was defeated and killed. Li Bai fled, was arrested at Pengze and jailed at Xunyang. His wife pleaded for him and the official Song Ruosi had him released for a time, but at the year's end he was sentenced to exile in Yelang, in present-day Guizhou."]),
      w(759, 109.57, 31.04,
        ['白帝城（今重庆奉节）', '流放夜郎途中遇赦，作《早发白帝城》', '李白溯长江西上赴夜郎，走了一年多，759年春行至三峡一带时，朝廷因关中大旱宣布大赦，他重获自由。他立即掉头东下，写下“朝辞白帝彩云间，千里江陵一日还。两岸猿声啼不住，轻舟已过万重山”。'],
        ["Baidicheng (Fengjie, Chongqing)", "Pardoned on the road to exile", "For over a year Li Bai travelled slowly up the Yangtze towards Yelang. In spring 759, as he reached the Three Gorges, a general amnesty proclaimed during a drought set him free. Turning back at once, he wrote 'Setting Out Early from Baidi': leaving the city among coloured clouds at dawn, a thousand li to Jiangling in a day, his light boat past ten thousand mountains."],
        { wiki: { zh: '白帝城', en: 'Baidicheng' } }),
      w(762, 118.49, 31.55,
        ['当涂（今安徽马鞍山当涂）', '病逝于族叔当涂县令李阳冰处', '遇赦后李白往来于江夏、浔阳、金陵、宣城之间。761年他听说李光弼出镇临淮，以年过六旬之身请缨从军，半路因病折回，投奔当涂县令、族叔李阳冰。762年冬他病重，把诗稿托付给李阳冰后去世；醉中入水捉月而死是后世的传说。'],
        ["Dangtu (Ma'anshan, Anhui)", "Dies at Dangtu in his kinsman's care", "After his pardon Li Bai drifted from town to town along the Yangtze. In 761, past sixty, he set out to join Li Guangbi's army but fell ill and turned back, taking shelter with his kinsman Li Yangbing, magistrate of Dangtu. In the winter of 762 he entrusted his manuscripts to Li Yangbing and died. The tale that he drowned reaching for the moon is a later legend."]),
    ],
    wiki: { zh: '李白', en: 'Li Bai' },
  },
  {
    id: 'charlemagne', name: { zh: '查理曼', en: 'Charlemagne' }, birth: 748, death: 814, approx: true,
    title: { zh: '法兰克国王、皇帝', en: 'King of the Franks and emperor' }, region: 'europe', lineage: 'france', sprite: 'crown',
    summary: {
      zh: '法兰克国王，加洛林王朝最著名的君主，被称为“欧洲之父”。他四方征战四十余年，将西欧和中欧大部分地区统一于法兰克王国，800年由教宗加冕为“罗马人的皇帝”。他以亚琛为中心推动文化复兴，史称“加洛林文艺复兴”，其帝国后来分裂为法、德、意诸国的雏形。',
      en: "King of the Franks and the best-known ruler of the Carolingian dynasty, often called the 'Father of Europe'. In more than forty years of campaigning he brought most of western and central Europe under Frankish rule, and on Christmas Day 800 the pope crowned him emperor of the Romans. From his court at Aachen he promoted the revival of learning known as the Carolingian Renaissance. After his death his empire was divided into realms that foreshadowed France, Germany and Italy.",
    },
    route: [
      w(748, 5.63, 50.67,
        ['赫斯塔尔（今比利时列日附近，出生地不详）', '生于法兰克宫相之家', '查理是法兰克宫相“矮子”丕平与贝尔特拉达的长子，生年有742年、747年、748年等说法，出生地也没有记载，传统上多认为在家族领地集中的列日一带。751年丕平废黜墨洛温王朝末代国王，自立为王，开创加洛林王朝。'],
        ["Herstal (near Liège, Belgium; birthplace uncertain)", "Born into the family of the Frankish mayors", "Charles was the eldest son of Pepin the Short, mayor of the palace, and Bertrada. The year is given as 742, 747 or 748, and no source names the place; tradition favours the family estates around Liège. In 751 Pepin deposed the last Merovingian king and took the crown, founding the Carolingian dynasty."]),
      w(754, 2.36, 48.936,
        ['圣但尼修道院（巴黎以北）', '由教宗为父子三人行涂油礼', '教宗斯德望二世为求法兰克人出兵对付伦巴第人，翻越阿尔卑斯山来到法兰克，年幼的查理曾奉父命前去迎接。754年7月，教宗在圣但尼为丕平和他的两个儿子查理、卡洛曼行涂油礼，确认了新王朝的合法性。'],
        ["Abbey of Saint-Denis (north of Paris)", "Anointed by the pope with his father and brother", "Pope Stephen II crossed the Alps to ask the Franks for help against the Lombards, and the young Charles was sent to meet him on the road. In July 754, at Saint-Denis, the pope anointed Pepin and his two sons, Charles and Carloman, confirming the legitimacy of the new royal line."]),
      w(768, 3.0, 49.58,
        ['努瓦永（今法国北部）', '与弟卡洛曼分治法兰克王国，加冕为王', '768年9月丕平去世，王国按法兰克习俗由两个儿子平分。10月9日，查理在努瓦永、卡洛曼在苏瓦松同日即位。兄弟二人关系紧张，771年卡洛曼突然去世，查理接管了他的领地，成为法兰克唯一的国王。'],
        ["Noyon (northern France)", "Crowned king, sharing the realm with Carloman", "Pepin died in September 768 and the kingdom was divided between his sons in the Frankish manner. On 9 October Charles was raised to the kingship at Noyon and Carloman at Soissons. The brothers were on poor terms. When Carloman died suddenly in 771, Charles took over his lands and became sole king of the Franks."]),
      w(772, 8.85, 51.45,
        ['埃雷斯堡（今德国马尔斯贝格）', '首征萨克森，捣毁伊尔明苏尔', '772年查理第一次进攻尚未皈依基督教的萨克森人，攻下埃雷斯堡要塞，捣毁了萨克森人崇拜的圣柱“伊尔明苏尔”。萨克森战争由此开始，断断续续打了三十多年，直到804年才告结束。'],
        ["Eresburg (now Marsberg, Germany)", "First Saxon campaign; destroys the Irminsul", "In 772 Charles made his first attack on the pagan Saxons, took the hill fort of Eresburg and destroyed the Irminsul, a sacred pillar they venerated. It was the opening of the Saxon Wars, which were to drag on, with many interruptions, for more than thirty years until 804."],
        { wiki: { zh: '萨克森战争', en: 'Saxon Wars' } }),
      w(774, 9.16, 45.19,
        ['帕维亚（伦巴第王国都城，今意大利北部）', '攻灭伦巴第王国', '应教宗哈德良一世之请，查理于773年翻越阿尔卑斯山，围攻伦巴第都城帕维亚。围城期间，他在774年复活节第一次到罗马，重申了父亲对教宗的土地赠与。6月帕维亚投降，国王德西德里乌斯被送进修道院，查理自称“法兰克人和伦巴第人的国王”。'],
        ["Pavia (Lombard capital, northern Italy)", "Conquers the Lombard kingdom", "At the appeal of Pope Hadrian I, Charles crossed the Alps in 773 and besieged the Lombard capital, Pavia. During the siege he went to Rome for Easter 774, his first visit, and renewed his father's grant of lands to the papacy. Pavia fell in June, King Desiderius was sent to a monastery, and Charles styled himself king of the Franks and the Lombards."]),
      w(778, -0.88, 41.65,
        ['萨拉戈萨（今西班牙东北部）', '远征西班牙，围攻萨拉戈萨不克', '777年，巴塞罗那和萨拉戈萨的穆斯林总督到帕德博恩求见，请查理出兵对付科尔多瓦的埃米尔。次年他率军越过比利牛斯山，萨拉戈萨却闭门不纳。围城一个多月无果，又传来萨克森人再度起事的消息，他只得撤兵，途中拆毁了潘普洛纳的城墙。'],
        ["Zaragoza (north-eastern Spain)", "Marches into Spain; fails before Zaragoza", "In 777 Muslim governors from Barcelona and Zaragoza came to Paderborn to seek Charles's help against the emir of Cordoba. The next year he led an army over the Pyrenees, but Zaragoza shut its gates. After a fruitless siege of over a month, and with news of a fresh Saxon rising, he withdrew, pulling down the walls of Pamplona on the way."],
        { via: [[0.37, 46.65], [-1.64, 42.82]] }),
      w(778, -1.32, 43.01,
        ['龙塞斯瓦列斯山口（比利牛斯山）', '后卫在山口遇袭，《罗兰之歌》的原型', '778年8月15日，法兰克军队翻越比利牛斯山返回时，殿后的部队和辎重在龙塞斯瓦列斯山口遭巴斯克人伏击，全军覆没，阵亡者中有布列塔尼边区长官罗兰。三百年后，这场败仗被改写成对抗撒拉森人的史诗《罗兰之歌》。'],
        ["Roncevaux Pass (Pyrenees)", "Rearguard ambushed; the origin of the Song of Roland", "On 15 August 778, as the Frankish army recrossed the Pyrenees, Basques ambushed its rearguard and baggage train in the pass of Roncevaux and wiped it out. Among the dead was Roland, warden of the Breton March. Three centuries later the defeat was recast as a battle against Saracens in the epic Song of Roland."],
        { wiki: { zh: '罗兰之歌', en: 'The Song of Roland' } }),
      w(782, 9.23, 52.92,
        ['费尔登（今德国下萨克森）', '镇压萨克森起义，费尔登处决', '782年，萨克森首领维杜金德起事，在松特尔山歼灭了一支法兰克军队。查理赶到阿勒尔河畔的费尔登，迫使萨克森贵族交出参与者，据《法兰克王家年代记》，一天之内处决了四千五百人。他为萨克森颁布的法令规定，拒绝受洗者处死。'],
        ["Verden (Lower Saxony, Germany)", "Crushes a Saxon revolt; the executions at Verden", "In 782 the Saxon leader Widukind rose in revolt and destroyed a Frankish force in the Süntel hills. Charles marched to Verden on the Aller and made the Saxon nobles hand over those involved; the Royal Frankish Annals say that 4,500 were executed in a single day. His laws for Saxony made refusal of baptism punishable by death."]),
      w(785, 8.75, 51.72,
        ['帕德博恩（今德国北莱茵-威斯特法伦）', '维杜金德归降，萨克森大体平定', '查理在萨克森腹地的帕德博恩建有行宫和教堂，多次在此召集大会。785年他在萨克森过冬并在这里集会之后，一直率众抵抗的维杜金德终于归降，到阿蒂尼受洗，由查理亲自做教父。萨克森战争此后仍有反复，前后历时三十余年才最终结束。'],
        ["Paderborn (North Rhine-Westphalia, Germany)", "Widukind submits; Saxony largely subdued", "At Paderborn, deep in Saxon territory, Charles had built a palace and church where he held several assemblies. After he wintered in Saxony and held an assembly here in 785, Widukind at last gave up the struggle and was baptised at Attigny, with Charles as his godfather. Revolts flared again, and the wars ended for good only after more than thirty years."]),
      w(788, 8.06, 49.97,
        ['因格尔海姆（今德国美因茨附近）', '废黜巴伐利亚公爵塔西洛', '巴伐利亚公爵塔西洛三世是查理的表兄，长期保持半独立地位。788年查理在因格尔海姆行宫召开大会，以塔西洛早年临阵脱逃、又勾结阿瓦尔人为由判他死罪，后改为送入修道院。巴伐利亚并入法兰克王国，查理的疆土由此与阿瓦尔人接壤。'],
        ["Ingelheim (near Mainz, Germany)", "Deposes Duke Tassilo of Bavaria", "Tassilo III of Bavaria, Charles's cousin, had long ruled in near independence. At an assembly in the palace of Ingelheim in 788 he was condemned to death for an old act of desertion and for dealings with the Avars, a sentence commuted to confinement in a monastery. Bavaria was absorbed into the Frankish kingdom, which now bordered the Avars."]),
      w(791, 12.1, 49.02,
        ['雷根斯堡（今德国巴伐利亚）', '自雷根斯堡出征阿瓦尔人', '791年查理在雷根斯堡集结大军，沿多瑙河两岸东进，深入阿瓦尔人境内直到拉布河。此后两年他常驻雷根斯堡，793年还试图开凿运河连通莱茵河与多瑙河水系，未能成功。796年，他的儿子丕平攻破阿瓦尔人的大营“环城”，缴获大批金银。'],
        ["Regensburg (Bavaria, Germany)", "Launches the Avar war from Regensburg", "In 791 Charles assembled a great army at Regensburg and advanced down both banks of the Danube into Avar territory as far as the Raab. Based there for the next two years, he tried in 793, without success, to dig a canal linking the Rhine and Danube basins. In 796 his son Pepin took the Avar 'Ring' and its hoard of treasure."]),
      w(794, 8.68, 50.11,
        ['法兰克福（今德国黑森）', '主持法兰克福宗教会议', '794年查理在美因河畔的法兰克福召集主教会议，谴责西班牙的“嗣子说”异端，并否定787年拜占庭第二次尼西亚公会议关于圣像崇敬的决议；会议还规定了新铸银币的通行和粮食的最高价格。这是法兰克福这个地名第一次见于文献。'],
        ["Frankfurt (Hesse, Germany)", "Presides over the Council of Frankfurt", "In 794 Charles gathered his bishops at Frankfurt on the Main. The council condemned the Adoptionist teaching current in Spain and rejected the decrees on the veneration of images issued by the Byzantine council of Nicaea in 787; it also dealt with the reformed silver coinage and maximum grain prices. The meeting is the first recorded mention of Frankfurt."]),
      w(796, 6.08, 50.78,
        ['亚琛（今德国西部）', '营建亚琛宫廷与宫廷礼拜堂', '查理原先没有固定的都城，大约从794年起，每年冬天都住在以温泉著称的亚琛，并在这里兴建宫殿。八角形的宫廷礼拜堂由梅斯的奥多设计，仿照拉文纳的圣维塔莱教堂，石柱和大理石从罗马、拉文纳运来，约在800年前后建成，今为亚琛主教座堂的核心。'],
        ["Aachen (western Germany)", "Builds his palace and chapel at Aachen", "Charles had no fixed capital, but from about 794 he spent nearly every winter at Aachen, known for its hot springs, and built a palace there. Its octagonal chapel, designed by Odo of Metz on the model of San Vitale in Ravenna and fitted with columns and marble brought from Rome and Ravenna, was finished around 800 and forms the core of Aachen Cathedral."],
        { wiki: { zh: '亚琛主教座堂', en: 'Aachen Cathedral' } }),
      w(799, 8.75, 51.72,
        ['帕德博恩', '在帕德博恩会见教宗利奥三世', '799年4月，教宗利奥三世在罗马街头遭政敌袭击，被囚后逃脱，北上到帕德博恩向查理求助。查理以盛大仪式迎接，随后派人护送他回罗马复位，并答应亲自前去审理对教宗的指控。这次会面为次年的加冕埋下了伏笔。'],
        ["Paderborn", "Receives Pope Leo III at Paderborn", "In April 799 Pope Leo III was attacked in the streets of Rome by his enemies, imprisoned and escaped, and he made his way north to seek Charles's help at Paderborn. Charles received him with great ceremony, had him escorted back to Rome and restored, and undertook to come in person to judge the charges against him. The meeting set the stage for the coronation."]),
      w(800, 12.4534, 41.9022,
        ['罗马圣彼得大教堂', '圣诞节被教宗加冕为“罗马人的皇帝”', '查理于800年11月到达罗马，教宗利奥三世当众宣誓自证清白。12月25日，查理在圣彼得大教堂望弥撒时，教宗把皇冠戴在他头上，会众高呼他为“奥古斯都”和皇帝。据艾因哈德说，查理事先并不知情；君士坦丁堡直到812年才承认他的帝号。'],
        ["St Peter's Basilica, Rome", "Crowned emperor of the Romans on Christmas Day", "Charles reached Rome in November 800, and Pope Leo cleared himself by a public oath. On 25 December, as Charles attended Mass in St Peter's, the pope set a crown on his head and the congregation acclaimed him Augustus and emperor. His biographer Einhard claims he had not known of the plan. Constantinople recognised his title only in 812."],
        { event: 'charlemagne-coronation' }),
      w(802, 6.08, 50.78,
        ['亚琛', '整顿帝国，倡导学术', '称帝后查理大多留在亚琛。802年他要求全体自由人重新宣誓效忠，并派“钦差”成对巡视各地。他延揽阿尔昆等学者，命教堂和修道院办学、抄书，字形清晰的加洛林小写体由此推广。同年，哈里发哈伦·拉希德所赠的大象阿布·阿拔斯运抵亚琛。'],
        ["Aachen", "Orders the empire and fosters learning", "As emperor Charles seldom left Aachen for long. In 802 he required a new oath of loyalty from all free men and sent royal envoys, the missi dominici, to inspect the provinces. Scholars such as Alcuin served him, and cathedrals and monasteries were told to keep schools and copy books, spreading the Carolingian minuscule. That year the elephant Abul-Abbas arrived, a gift from the caliph Harun al-Rashid."],
        { wiki: { zh: '加洛林文艺复兴', en: 'Carolingian Renaissance' } }),
      w(814, 6.08, 50.78,
        ['亚琛', '病逝，葬于亚琛大教堂', '813年9月，查理在亚琛的宫廷礼拜堂为唯一在世的嫡子路易加冕，立为共治皇帝。次年1月28日他因胸膜炎病逝，在位四十五年有余，当天葬在礼拜堂内。843年《凡尔登条约》把帝国分给他的三个孙子，形成后来法、德、意的雏形。'],
        ["Aachen", "Dies and is buried in his chapel at Aachen", "In September 813 Charles had Louis, his only surviving legitimate son, crowned co-emperor in the palace chapel at Aachen. He died of pleurisy on 28 January 814 after a reign of more than forty-five years and was buried in the chapel the same day. In 843 the Treaty of Verdun divided the empire among three grandsons, the outline of later France, Germany and Italy."]),
    ],
    wiki: { zh: '查理曼', en: 'Charlemagne' },
  },
];
